		return true;
	}

	@ConfigItem(
		keyName = "herbBoxes",
		name = "Herb boxes",
		description = "Buy herb boxes with Nightmare Zone points",
		section = DAILIES,
		position = 7
	)
	default boolean herbBoxes()
	{
