@PluginDescriptor(
	name = "Codex Rounds",
	description = "Your bird houses, seaweed, special trees and patches, diary dailies and Kingdom of Miscellania in one guided round",
	tags = {"farming", "birdhouse", "seaweed", "hardwood", "calquat", "spirit tree", "daily", "miscellania", "kingdom", "route", "codex"}
)
@PluginDependency(BankTagsPlugin.class)
public class CodexRoundsPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexRoundsPlugin.class);
	private static final String MEMORY_KEY = "memory";
	private static final String TIME_TRACKING = "timetracking";
	private static final String KINGDOM = "kingdomofmiscellania";
	private static final int SAVE_TICKS = 50;
	private static final int ACCOUNT_TICKS = 5;
	private static final int QUEST_TICKS = 100;
	private static final int PUBLISH_TICKS = 10;
	private static final int SCAN_RADIUS = 10;
	/** Quetzal landing sites built, as bits of the quetzals varp (from the Shortest Path plugin's data). */
	private static final int QUETZAL_KASTORI_BIT = 16384;
	private static final int QUETZAL_WYRM_BIT = 64;
	/** The bank tab holding the round's pull list. */
	static final String BANK_TAG = "codex rounds";

	private static final Pattern COMPOST = Pattern.compile(
		"(You treat the .+ with (ultra|super|)compost\\.)|(The .+ has been treated with (ultra|super|)compost.*)"
			+ "|(This .+ has already been (treated|fertilised) with (ultra|super|)compost.*)");
	private static final String[] PAID = {
		"Leave it with me", "look after that nursery", "protects your tree for you",
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Notifier notifier;

	@Inject
	private Gson gson;

	@Inject
	private CodexRoundsConfig config;

	@Inject
	private BankTagsService bankTags;

	@Inject
	private TagManager tagManager;

	@Inject
	private LayoutManager layoutManager;

	@Inject
	private TargetOverlay targetOverlay;

	@Inject
	private ItemHighlight itemHighlight;

	private final StepPlaque plaque = new StepPlaque();
	private final Progress progress = new Progress();
	private final TravelTimer timer = new TravelTimer();

	private RoundsPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Memory memory;
	private Settings settings = Settings.defaults();
	private Growth.Offset offset = Growth.Offset.NONE;
	private Board board;
	private Route route = Route.EMPTY;
	private Step step = Step.IDLE;
	private Map<Integer, Integer> carried = Collections.emptyMap();
	private volatile Set<Integer> tabItems = Collections.emptySet();
	private boolean tabOpened;
	private boolean tabWanted;
	/** The running round covers only bird houses and seaweed. */
	private boolean quick;
	private boolean dirty;
	private boolean unsaved;
	private boolean replan = true;
	/** A running round keeps its route; only starting it or pressing Replan plans it again. */
	private boolean roundReplan;
	private int ticks;
	private String published;
	private boolean notified;
	private WorldMapPoint mapPoint;
	private String arrowKey;

	@Provides
	CodexRoundsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexRoundsConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new RoundsPanel(icons, new PanelActions());
		navButton = NavigationButton.builder()
			.tooltip("Codex Rounds")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		overlayManager.add(targetOverlay);
		overlayManager.add(itemHighlight);
		tagManager.registerTag(BANK_TAG, id -> tabItems.contains(id));
		settings = readSettings();
		clientThread.invokeLater(() ->
		{
			loadProfile();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				carried = readCarried();
			}
			refresh(true);
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		overlayManager.remove(targetOverlay);
		overlayManager.remove(itemHighlight);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			if (BANK_TAG.equals(bankTags.getActiveTag()))
			{
				bankTags.closeBankTag();
			}
			tagManager.unregisterTag(BANK_TAG);
			layoutManager.removeLayout(BANK_TAG);
			save();
			clearGuidance();
			memory = null;
			profile = null;
			progress.stop();
			quick = false;
			timer.reset();
		});
		panel = null;
	}

	// ---- Events ----

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.BANKMAIN)
		{
			return;
		}
		tabOpened = false;
		// Opening the bank mid-way through gathering supplies goes straight to the round's tab.
		if (tabWanted || config.bankTab() && progress.isStarted() && step.getKind() == Step.Kind.SUPPLIES && step.getTarget() == null)
		{
			tabWanted = false;
			clientThread.invokeLater(this::openBankTab);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			save();
			clearGuidance();
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			ticks = 0;
			replan = true;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		String key = configManager.getRSProfileKey();
		if (key == null || key.equals(profile))
		{
			// Logging out or a disconnect keeps the round; it carries on when the same account is back.
			save();
			return;
		}
		save();
		progress.stop();
		quick = false;
		timer.reset();
		loadProfile();
		replan = true;
		refresh(true);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexRoundsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			settings = readSettings();
			replan = true;
			refresh(true);
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (memory == null)
		{
			return;
		}
		if (id == InventoryID.BANK)
		{
			memory.bank = contents(event.getItemContainer());
			memory.bankTime = Instant.now().getEpochSecond();
			unsaved = true;
			dirty = true;
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			carried = readCarried();
			memory.carried = new HashMap<>(carried);
			dirty = true;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = event.getMessage();
		if (msg.contains("compost") && COMPOST.matcher(msg).matches())
		{
			Spot spot = spotBeside();
			if (spot != null)
			{
				progress.composted(spot, Instant.now().getEpochSecond());
				dirty = true;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (memory == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		long now = Instant.now().getEpochSecond();
		WorldPoint wp = me.getWorldLocation();
		Point loc = Point.of(wp.getX(), wp.getY(), wp.getPlane());

		readSpots(loc, now);
		if (ticks % ACCOUNT_TICKS == 0)
		{
			readAccount(now, ticks % QUEST_TICKS == 0);
		}
		readPayment();
		ticks++;

		refresh(false);

		if (unsaved && ticks % SAVE_TICKS == 0)
		{
			save();
		}
	}

	// ---- Reading the game ----

	private void readSpots(Point loc, long now)
	{
		if (client.isMenuOpen())
		{
			return;
		}
		// Varbits are not sent while a modal interface is open, as RuneLite's Time Tracking notes.
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getModalMode() != WidgetModalMode.NON_MODAL)
			{
				return;
			}
		}
		int removals = 0;
		Map<Spot, Integer> houses = new EnumMap<>(Spot.class);
		for (Spot spot : Spot.values())
		{
			if (!spot.readableFrom(loc))
			{
				continue;
			}
			if (spot.isBirdhouse())
			{
				int v = client.getVarpValue(spot.getVarp());
				Seen old = memory.seen(spot);
				if (old == null || old.getValue() != v)
				{
					houses.put(spot, v);
					if (v <= 0 && old != null && old.getValue() > 0)
					{
						removals++;
					}
				}
				continue;
			}
			int v = client.getVarbitValue(spot.getVarbit());
			PatchState now0 = spot.getKind().forVarbitValue(v);
			if (now0 == null)
			{
				continue;
			}
			Seen old = memory.seen(spot);
			if (old == null || old.getValue() != v)
			{
				PatchState before = old == null ? null : spot.getKind().forVarbitValue(old.getValue());
				memory.put(spot, new Seen(v, now));
				if ((before == null || before.isEmpty()) && !now0.isEmpty() && now0.getCropState() == CropState.GROWING && now0.getStage() == 0)
				{
					progress.planted(spot, now);
				}
				dirty = true;
				unsaved = true;
			}
			else if (old.getTime() + 300 < now)
			{
				// Same state still: refresh the time so predictions run from the latest look.
				memory.put(spot, new Seen(v, now));
				unsaved = true;
			}
		}
		// The bird house varps can read zero for a moment after arriving; four at once dropping to
		// nothing is not something a player can do (RuneLite's bird house tracker uses the same guard).
		if (removals <= 2 && !houses.isEmpty())
		{
			houses.forEach((s, v) -> memory.put(s, new Seen(v, now)));
			dirty = true;
			unsaved = true;
		}
	}

	private final Vars vars = new Vars()
	{
		@Override
		public int varbit(int id)
		{
			return client.getVarbitValue(id);
		}

		@Override
		public int varp(int id)
		{
			return client.getVarpValue(id);
		}
	};

	private void readAccount(long now, boolean quests)
	{
		int farming = client.getRealSkillLevel(Skill.FARMING);
		int hunter = client.getRealSkillLevel(Skill.HUNTER);
		int crafting = client.getRealSkillLevel(Skill.CRAFTING);
		int magic = client.getRealSkillLevel(Skill.MAGIC);
		int book = client.getVarbitValue(VarbitID.SPELLBOOK);
		if (farming != memory.farming || hunter != memory.hunter || crafting != memory.crafting || magic != memory.magic || book != memory.spellbook)
		{
			memory.farming = farming;
			memory.hunter = hunter;
			memory.crafting = crafting;
			memory.magic = magic;
			memory.spellbook = book;
			dirty = true;
			unsaved = true;
		}

		int contract = Contract.complete(vars) ? 0 : Contract.type(vars);
		if (contract != memory.contractType)
		{
			memory.contractType = contract;
			dirty = true;
			unsaved = true;
		}

		Map<Integer, Integer> stored = Leprechaun.read(vars);
		if (!stored.equals(memory.stored))
		{
			memory.stored = stored;
			dirty = true;
			unsaved = true;
		}

		for (Daily d : Daily.values())
		{
			DailyState st = DailyState.of(d, vars);
			Memory.DailySnap old = memory.dailies == null ? null : memory.dailies.get(d.name());
			if (old == null || old.claimable != st.isClaimable() || old.unlocked != st.isUnlocked() || now / 86400 != old.seenAt / 86400
				|| !st.getReward().equals(old.reward))
			{
				memory.snapDaily(st, now);
				dirty = true;
				unsaved = true;
			}
		}

		boolean quest = client.getVarpValue(VarPlayerID.MISC_QUEST) > 0;
		if (quest != memory.kingdomQuest)
		{
			memory.kingdomQuest = quest;
			dirty = true;
			unsaved = true;
		}
		if (quest)
		{
			int coffer = client.getVarbitValue(VarbitID.MISC_COFFERS);
			int approval = client.getVarbitValue(VarbitID.MISC_APPROVAL);
			boolean inKingdom = false;
			Player me = client.getLocalPlayer();
			if (me != null)
			{
				int region = me.getWorldLocation().getRegionID();
				for (int r : Kingdom.REGIONS)
				{
					inKingdom |= r == region;
				}
			}
			if ((inKingdom || coffer > 0 && approval > 0)
				&& (memory.kingdomCoffer == null || memory.kingdomCoffer != coffer || memory.kingdomApproval == null || memory.kingdomApproval != approval))
			{
				memory.kingdomCoffer = coffer;
				memory.kingdomApproval = approval;
				memory.kingdomTime = now;
				dirty = true;
				unsaved = true;
			}
		}

		if (quests)
		{
			boolean rt = Quest.ROYAL_TROUBLE.getState(client) == QuestState.FINISHED;
			boolean fairy = Quest.FAIRYTALE_II__CURE_A_QUEEN.getState(client) != QuestState.NOT_STARTED
				&& (client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) == 1 || memory.ability().owns(Teleports.FAIRY_STAFFS));
			if (rt != memory.royalTrouble || fairy != memory.fairyRings)
			{
				memory.royalTrouble = rt;
				memory.fairyRings = fairy;
				dirty = true;
				unsaved = true;
			}
			Set<String> unlocks = readUnlocks();
			if (!unlocks.equals(memory.unlocks))
			{
				memory.unlocks = unlocks;
				dirty = true;
				unsaved = true;
			}
		}
	}

	private Set<String> readUnlocks()
	{
		Set<String> out = new HashSet<>();
		addIf(out, Unlock.FREMENNIK_TRIALS, finished(Quest.THE_FREMENNIK_TRIALS));
		addIf(out, Unlock.CHILDREN_OF_THE_SUN, finished(Quest.CHILDREN_OF_THE_SUN));
		addIf(out, Unlock.GREAT_CONCH, Quest.TROUBLED_TORTUGANS.getState(client) != QuestState.NOT_STARTED);
		addIf(out, Unlock.THRONE_OF_MISCELLANIA, finished(Quest.THRONE_OF_MISCELLANIA));
		addIf(out, Unlock.SONG_OF_THE_ELVES, finished(Quest.SONG_OF_THE_ELVES));
		addIf(out, Unlock.BONE_VOYAGE, finished(Quest.BONE_VOYAGE));
		addIf(out, Unlock.PLAGUE_CITY, finished(Quest.PLAGUE_CITY));
		int quetzals = client.getVarpValue(VarPlayerID.QUETZALS_UNLOCKED);
		addIf(out, Unlock.QUETZAL_KASTORI, (quetzals & QUETZAL_KASTORI_BIT) != 0);
		addIf(out, Unlock.QUETZAL_WYRM, (quetzals & QUETZAL_WYRM_BIT) != 0);
		addIf(out, Unlock.ATES_KASTORI, client.getVarbitValue(VarbitID.PENDANT_OF_ATES_TLATI_FOUND) > 0);
		return out;
	}

	private boolean finished(Quest q)
	{
		return q.getState(client) == QuestState.FINISHED;
	}

	private static void addIf(Set<String> out, Unlock u, boolean has)
	{
		if (has)
		{
			out.add(u.name());
		}
	}

	/** Watches the gardener's chat box for the line that confirms a crop is protected. */
	private void readPayment()
	{
		if (!progress.isStarted() || step.getTask() == null || step.getTask().getSpot() == null || !step.getTask().isProtect())
		{
			return;
		}
		Widget text = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (text == null || text.isHidden() || text.getText() == null)
		{
			return;
		}
		String t = text.getText();
		for (String p : PAID)
		{
			if (t.contains(p))
			{
				Spot spot = step.getTask().getSpot();
				if (!progress.isPaid(spot))
				{
					progress.paid(spot, Instant.now().getEpochSecond());
					dirty = true;
				}
				return;
			}
		}
	}

	/** The spot the player is standing beside: the current step's if close, else any close one. */
	private Spot spotBeside()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		WorldPoint wp = me.getWorldLocation();
		Point p = Point.of(wp.getX(), wp.getY(), wp.getPlane());
		if (step.getTask() != null && step.getTask().getSpot() != null && step.getTask().getSpot().getPoint().distance(p) <= 4)
		{
			return step.getTask().getSpot();
		}
		Spot best = null;
		int bestD = 5;
		for (Spot s : Spot.values())
		{
			if (!s.isBirdhouse() && s.getPoint().sameMap(p) && s.getPoint().distance(p) < bestD)
			{
				best = s;
				bestD = s.getPoint().distance(p);
			}
		}
		return best;
	}

	private Map<Integer, Integer> readCarried()
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (int id : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer c = client.getItemContainer(id);
			if (c != null)
			{
				contents(c).forEach((k, v) -> out.merge(k, v, Integer::sum));
			}
		}
		return out;
	}

	private Map<Integer, Integer> contents(ItemContainer c)
	{
		Map<Integer, Integer> out = new HashMap<>();
		if (c == null)
		{
			return out;
		}
		for (Item item : c.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				out.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return out;
	}

	// ---- Planning and guiding ----

	private Map<Spot, Reading> readings(long now)
	{
		Map<Spot, Reading> out = new EnumMap<>(Spot.class);
		Map<Spot, Seen> seen = memory.seenMap();
		for (Spot s : Spot.values())
		{
			out.put(s, Growth.read(s, seen.get(s), now, offset));
		}
		return out;
	}

	private List<DailyState> dailies(long now)
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			List<DailyState> out = new ArrayList<>();
			for (Daily d : Daily.values())
			{
				out.add(DailyState.of(d, vars));
			}
			return out;
		}
		return memory.dailyStates(now);
	}

	/** Rebuilds the board, the round and the step, then pushes them to the panel and overlays. */
	private void refresh(boolean force)
	{
		if (memory == null)
		{
			publish(force);
			return;
		}
		long now = Instant.now().getEpochSecond();
		settings.contract(settings.wants(Daily.CONTRACT) ? Contract.produce(memory.contractType) : null);
		Ability ability = memory.ability();
		List<DailyState> dailies = dailies(now);
		Kingdom kingdom = memory.kingdom(now);
		if (force || dirty || ticks % ACCOUNT_TICKS == 0)
		{
			board = Board.build(memory.seenMap(), dailies, kingdom, settings, ability, now, offset);
			if (!progress.isStarted() && (replan || ticks % 50 == 0 || dirty))
			{
				route = Planner.plan(board, dailies, settings, ability, here(), now);
				replan = false;
			}
			else if (progress.isStarted() && roundReplan)
			{
				// Chores already finished leave the new plan, so bank them for the round's tally.
				progress.bank(step.getDone(), step.getStopIndex() < 0 ? 0 : step.getStopIndex());
				route = Planner.plan(board, dailies, roundSettings(), ability, here(), now);
				roundReplan = false;
				replan = false;
			}
			dirty = false;
			notifyIfReady();
		}

		Map<Daily, DailyState> dailyMap = new EnumMap<>(Daily.class);
		for (DailyState d : dailies)
		{
			dailyMap.put(d.getDaily(), d);
		}
		Guide.World world = new Guide.World(here(), readings(now), dailyMap, kingdom, carried, ability, now);
		Step next = progress.isStarted() ? Guide.next(route, world, progress, roundSettings()) : Guide.next(route, world, new Progress(), settings);
		step = next;

		if (progress.isStarted() && route.isEmpty())
		{
			// Nothing left to plan (or nothing was due): a round with no chores is over.
			finishRound(now);
			next = Step.IDLE;
			step = next;
		}
		if (progress.isStarted())
		{
			if (!route.isEmpty() && route.getStops().get(0).getPlace().contains(here()))
			{
				progress.suppliesDone();
			}
			TravelTimer.Lap lap = timer.update(next, route, here(), ability, System.currentTimeMillis());
			if (lap != null)
			{
				memory.lap(lap.getKey(), lap.getSeconds());
				unsaved = true;
			}
			if (next.getKind() == Step.Kind.IDLE && next.getTotal() > 0 && next.getDone() >= next.getTotal())
			{
				finishRound(now);
			}
		}
		guide();
		publish(force);
	}

	private Point here()
	{
		Player me = client.getLocalPlayer();
		if (me == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		WorldPoint wp = me.getWorldLocation();
		return Point.of(wp.getX(), wp.getY(), wp.getPlane());
	}

	/** Lays the pull list out as a bank tab and opens it; only while the bank is open. */
	private void openBankTab()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden() || route.isEmpty() || tabOpened)
		{
			return;
		}
		tabOpened = true;
		// The tab is drawn by RuneLite's Bank Tags plugin, which can be switched off.
		if ("false".equals(configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, "banktagsplugin")))
		{
			chat("turn on RuneLite's Bank Tags plugin to see the round as a bank tab.");
			return;
		}
		Map<Integer, Integer> held = memory == null || memory.bank == null ? Collections.emptyMap() : memory.bank;
		tabItems = BankTab.items(route.getPulls());
		layoutManager.saveLayout(new Layout(BANK_TAG, BankTab.layout(route.getPulls(), held)));
		bankTags.openBankTag(BANK_TAG, 0);
	}

	/** "Wait 14 min and 5 more join: giant seaweed and bird houses." */
	/** The settings the running round was planned with: a quick loop narrows them. */
	private Settings roundSettings()
	{
		return quick && progress.isStarted() ? settings.quickLoop() : settings;
	}

	private String forecastText(long now)
	{
		if (board == null)
		{
			return null;
		}
		Board.Forecast f = board.forecast(now + settings.getLookaheadMinutes() * 60L);
		if (f == null)
		{
			return null;
		}
		List<String> g = f.getGroups();
		String what = g.size() == 1 ? g.get(0) : String.join(", ", g.subList(0, g.size() - 1)) + " and " + g.get(g.size() - 1);
		return (route.isEmpty() ? "Wait " + Format.duration(f.getWaitSeconds()) + " and " + f.getMore() + " come ready: "
			: "Wait " + Format.duration(f.getWaitSeconds()) + " and " + f.getMore() + " more join: ") + what + ".";
	}

	private void chat(String text)
	{
		String msg = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("Codex Rounds: ")
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(msg).build());
	}

	private void finishRound(long now)
	{
		int seconds = (int) (now - progress.getStartedAt());
		int chores = progress.getBankedChores() + route.taskCount();
		int stops = progress.getBankedStops() + route.getStops().size();
		progress.stop();
		if (chores == 0)
		{
			quick = false;
			timer.reset();
			replan = true;
			chat("nothing is due right now, so there is no round to run.");
			return;
		}
		memory.record(new Memory.RoundRecord(now, seconds, chores, stops));
		unsaved = true;
		quick = false;
		timer.reset();
		replan = true;
		if (config.chatSummary())
		{
			chat("round complete in " + Format.clock(seconds) + ", " + chores + (chores == 1 ? " chore at " : " chores at ")
				+ stops + (stops == 1 ? " stop." : " stops."));
		}
	}

	private void notifyIfReady()
	{
		if (board == null || progress.isStarted())
		{
			return;
		}
		long ready = board.count(Status.READY);
		if (ready >= config.notifyAt())
		{
			if (!notified && config.notifyReady() && client.getGameState() == GameState.LOGGED_IN && ticks > 10)
			{
				notifier.notify("Codex Rounds: " + ready + " chores are ready for a round.");
			}
			notified = true;
		}
		else
		{
			notified = false;
		}
	}

	/** Points the way: plaque, outline, hint arrow, item highlights and the map marker. */
	private void guide()
	{
		boolean on = progress.isStarted() && step.getKind() != Step.Kind.IDLE;
		if (!on)
		{
			clearGuidance();
			return;
		}
		String over;
		if (step.getKind() == Step.Kind.SUPPLIES)
		{
			over = "Before you set out";
		}
		else
		{
			Stop stop = route.getStops().get(Math.max(0, step.getStopIndex()));
			over = "Stop " + (step.getStopIndex() + 1) + " of " + route.getStops().size() + ": " + stop.getPlace().getLabel();
		}
		long now = Instant.now().getEpochSecond();
		plaque.show(config.plaque() ? new StepPlaque.Shown(over, step.getTitle(), step.getDetail(),
			Format.clock(now - progress.getStartedAt()), step.getDone(), step.getTotal()) : null);

		Set<Integer> items = new HashSet<>();
		for (int id : step.getItems())
		{
			items.add(id);
		}
		if (step.getKind() == Step.Kind.SUPPLIES)
		{
			items.addAll(step.getItems());
		}
		itemHighlight.setItems(items);

		resolveTarget();
		placeMapPoint();
	}

	private void clearGuidance()
	{
		plaque.show(null);
		itemHighlight.setItems(Collections.emptySet());
		targetOverlay.setResolved(null);
		if (arrowKey != null)
		{
			client.clearHintArrow();
			arrowKey = null;
		}
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
		}
	}

	private void resolveTarget()
	{
		Step.Target target = step.getTarget();
		if (target == null || client.getLocalPlayer() == null)
		{
			targetOverlay.setResolved(null);
			setArrow(null, null, null);
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		WorldPoint at = new WorldPoint(target.getPoint().getX(), target.getPoint().getY(), target.getPoint().getPlane());
		List<TileObject> objects = new ArrayList<>();
		NPC npc = null;
		switch (target.getType())
		{
			case SPOT:
			case OBJECT:
				objects = findObjects(wv, at, target);
				break;
			case NPC:
				int best = Integer.MAX_VALUE;
				for (NPC n : wv.npcs())
				{
					if (n != null && target.matches(n.getId()))
					{
						int d = n.getWorldLocation().distanceTo2D(at);
						if (d < best)
						{
							best = d;
							npc = n;
						}
					}
				}
				break;
			default:
				break;
		}
		targetOverlay.setResolved(new TargetOverlay.Resolved(objects, npc, at, step.getTitle()));
		setArrow(npc, objects.isEmpty() ? at : objects.get(0).getWorldLocation(), npc != null ? "npc" + npc.getIndex() : "pt" + at);
	}

	private List<TileObject> findObjects(WorldView wv, WorldPoint at, Step.Target target)
	{
		List<TileObject> out = new ArrayList<>();
		LocalPoint lp = LocalPoint.fromWorld(wv, at);
		if (lp == null)
		{
			return out;
		}
		Scene scene = wv.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = at.getPlane();
		if (plane < 0 || plane >= tiles.length)
		{
			return out;
		}
		Spot spot = target.getSpot();
		int sx = lp.getSceneX();
		int sy = lp.getSceneY();
		for (int x = Math.max(0, sx - SCAN_RADIUS); x <= Math.min(tiles[plane].length - 1, sx + SCAN_RADIUS); x++)
		{
			for (int y = Math.max(0, sy - SCAN_RADIUS); y <= Math.min(tiles[plane][x].length - 1, sy + SCAN_RADIUS); y++)
			{
				Tile tile = tiles[plane][x][y];
				if (tile == null)
				{
					continue;
				}
				for (GameObject go : tile.getGameObjects())
				{
					if (go == null || go.getSceneMinLocation() == null || !go.getSceneMinLocation().equals(tile.getSceneLocation()))
					{
						continue;
					}
					if (spot != null)
					{
						ObjectComposition def = client.getObjectDefinition(go.getId());
						if (def != null && (spot.isBirdhouse() ? def.getVarPlayerId() == spot.getVarp() : def.getVarbitId() == spot.getVarbit()))
						{
							out.add(go);
						}
					}
					else if (target.matches(go.getId()))
					{
						out.add(go);
					}
				}
			}
		}
		// Several patches can share a varbit in one scene; keep the one nearest the spot.
		if (out.size() > 1)
		{
			out.sort((a, b) -> Integer.compare(a.getWorldLocation().distanceTo2D(at), b.getWorldLocation().distanceTo2D(at)));
			return out.subList(0, 1);
		}
		return out;
	}

	private void setArrow(NPC npc, WorldPoint point, String key)
	{
		if (!config.hintArrow() || (npc == null && point == null))
		{
			if (arrowKey != null)
			{
				client.clearHintArrow();
				arrowKey = null;
			}
			return;
		}
		if (key.equals(arrowKey))
		{
			return;
		}
		if (npc != null)
		{
			client.setHintArrow(npc);
		}
		else
		{
			client.setHintArrow(point);
		}
		arrowKey = key;
	}

	private void placeMapPoint()
	{
		Point p = step.getMapPoint();
		if (!config.mapMarker() || p == null)
		{
			if (mapPoint != null)
			{
				worldMapPointManager.remove(mapPoint);
				mapPoint = null;
			}
			return;
		}
		WorldPoint wp = new WorldPoint(p.getX(), p.getY(), p.getPlane());
		if (mapPoint != null && wp.equals(mapPoint.getWorldPoint()))
		{
			return;
		}
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
		}
		mapPoint = WorldMapPoint.builder()
			.worldPoint(wp)
			.image(Sigil.icon(20))
			.name("Codex Rounds")
			.tooltip("Codex Rounds: " + step.getTitle())
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		worldMapPointManager.add(mapPoint);
	}

	private void publish(boolean force)
	{
		if (panel == null)
		{
			return;
		}
		long now = Instant.now().getEpochSecond();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		String sig = step.getTitle() + step.getDone() + "/" + step.getTotal() + "|" + route.taskCount() + "|" + route.getBuiltAt()
			+ "|" + (board == null ? -1 : board.count(Status.READY)) + "|" + progress.isStarted() + "|" + loggedIn + "|" + carried.hashCode();
		if (!force && sig.equals(published) && ticks % PUBLISH_TICKS != 0)
		{
			return;
		}
		published = sig;
		boolean known = memory != null && board != null && (loggedIn || !memory.seenMap().isEmpty());
		String last = null;
		if (memory != null && memory.rounds != null && !memory.rounds.isEmpty())
		{
			Memory.RoundRecord r = memory.rounds.get(memory.rounds.size() - 1);
			Memory.RoundRecord best = memory.best();
			last = "Last round: " + Format.clock(r.seconds) + " for " + r.chores + " chores." + (best != null && best != r ? " Fastest: " + Format.clock(best.seconds) + "." : "");
		}
		Map<Integer, Integer> bank = memory == null || memory.bank == null ? Collections.emptyMap() : new HashMap<>(memory.bank);
		View view = new View(loggedIn, known, board, route, step, progress.isStarted(), progress.getStartedAt(), now,
			memory != null && memory.bankTime > 0, new HashMap<>(carried), bank, last,
			memory == null || memory.stored == null ? Collections.emptyMap() : new HashMap<>(memory.stored),
			!route.isEmpty() && Leprechaun.PLACES.contains(route.getStops().get(0).getPlace()),
			forecastText(now));
		Progress snapshot = progress;
		Route r = route;
		Map<Spot, Reading> live = memory == null ? Collections.emptyMap() : readings(now);
		Map<Daily, DailyState> dailyMap = new EnumMap<>(Daily.class);
		if (memory != null)
		{
			for (DailyState d : dailies(now))
			{
				dailyMap.put(d.getDaily(), d);
			}
		}
		Guide.World world = new Guide.World(here(), live, dailyMap, memory == null ? null : memory.kingdom(now), carried,
			memory == null ? Ability.unknown() : memory.ability(), now);
		Settings rs = roundSettings();
		Set<String> doneKeys = new HashSet<>();
		long since = progress.isStarted() ? progress.getStartedAt() : r.getBuiltAt();
		for (Stop s : r.getStops())
		{
			for (Task t : s.getTasks())
			{
				if (snapshot.isStarted() && Guide.isDone(t, world, snapshot, rs, since))
				{
					doneKeys.add(Progress.key(t));
				}
			}
		}
		RoundsPanel p = panel;
		SwingUtilities.invokeLater(() -> p.update(view, t -> doneKeys.contains(Progress.key(t))));
	}

	// ---- Saved data ----

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		memory = null;
		if (profile == null)
		{
			return;
		}
		String saved = configManager.getRSProfileConfiguration(CodexRoundsConfig.GROUP, MEMORY_KEY);
		if (saved != null)
		{
			try
			{
				memory = gson.fromJson(saved, Memory.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Could not read saved rounds data", e);
			}
		}
		if (memory == null)
		{
			memory = new Memory();
		}
		adoptOutside();
		dirty = true;
	}

	/** Reads RuneLite's own Time Tracking and Kingdom plugins' saved data, without changing it. */
	private void adoptOutside()
	{
		for (Spot s : Spot.values())
		{
			String stored = configManager.getRSProfileConfiguration(TIME_TRACKING, s.timeTrackingKey());
			if (memory.adopt(s, Seen.parse(stored)))
			{
				unsaved = true;
			}
		}
		Integer offsetMins = configManager.getRSProfileConfiguration(TIME_TRACKING, "farmTickOffset", int.class);
		Integer precision = configManager.getRSProfileConfiguration(TIME_TRACKING, "farmTickOffsetPrecision", int.class);
		offset = new Growth.Offset(offsetMins, precision);

		Instant changed = configManager.getRSProfileConfiguration(KINGDOM, "lastChanged", Instant.class);
		Integer coffer = configManager.getRSProfileConfiguration(KINGDOM, "coffer", int.class);
		Integer approval = configManager.getRSProfileConfiguration(KINGDOM, "approval", int.class);
		if (changed != null && coffer != null && approval != null && changed.getEpochSecond() > memory.kingdomTime)
		{
			memory.kingdomTime = changed.getEpochSecond();
			memory.kingdomCoffer = coffer;
			memory.kingdomApproval = approval;
			memory.kingdomQuest = true;
			unsaved = true;
		}
	}

	private void save()
	{
		if (profile == null || memory == null || !unsaved)
		{
			return;
		}
		configManager.setConfiguration(CodexRoundsConfig.GROUP, profile, MEMORY_KEY, gson.toJson(memory));
		unsaved = false;
	}

	private Settings readSettings()
	{
		Settings s = Settings.defaults()
			.group(Spot.Group.BIRDHOUSES, config.birdhouses())
			.group(Spot.Group.SEAWEED, config.seaweed())
			.group(Spot.Group.HARDWOODS, config.hardwoods())
			.group(Spot.Group.TREES, config.specialTrees())
			.group(Spot.Group.SPIRIT_TREES, config.spiritTrees())
			.group(Spot.Group.PATCHES, config.specialPatches())
			.daily(Daily.ZAFF, config.zaff())
			.daily(Daily.CROMPERTY, config.cromperty())
			.daily(Daily.FLAX, config.flax())
			.daily(Daily.RANTZ, config.rantz())
			.daily(Daily.ROBIN, config.robin())
			.daily(Daily.THIRUS, config.thirus())
			.daily(Daily.BERT, config.bert())
			.daily(Daily.HERB_BOXES, config.herbBoxes())
			.daily(Daily.LUNDAIL, config.lundail())
			.daily(Daily.CONTRACT, config.contract())
			.kingdom(config.kingdom())
			.kingdomTargets(config.approvalTarget(), config.cofferTarget(), config.topUpSlack())
			.compost(config.compost())
			.protect(config.protect())
			.keepSpiritTrees(config.keepSpiritTrees())
			.includeUnseen(config.includeUnseen())
			.lookahead(config.lookahead());
		s.crop(com.codex.rounds.core.farming.PatchKind.HARDWOOD_TREE, produce(config.hardwood().name()));
		s.crop(com.codex.rounds.core.farming.PatchKind.BUSH, produce(config.bush().name()));
		s.crop(com.codex.rounds.core.farming.PatchKind.CACTUS, produce(config.cactus().name()));
		s.crop(com.codex.rounds.core.farming.PatchKind.ANIMA, produce(config.anima().name()));
		return s;
	}

	private static Produce produce(String name)
	{
		if ("BEST".equals(name))
		{
			return null;
		}
		try
		{
			return Produce.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private class PanelActions implements Actions
	{
		@Override
		public void start()
		{
			begin(false);
		}

		@Override
		public void startQuick()
		{
			begin(true);
		}

		private void begin(boolean quickLoop)
		{
			clientThread.invokeLater(() ->
			{
				quick = quickLoop;
				progress.start(Instant.now().getEpochSecond());
				timer.reset();
				replan = true;
				roundReplan = true;
				refresh(true);
			});
		}

		@Override
		public void stop()
		{
			clientThread.invokeLater(() ->
			{
				progress.stop();
				quick = false;
				timer.reset();
				replan = true;
				refresh(true);
			});
		}

		@Override
		public void skip()
		{
			clientThread.invokeLater(() ->
			{
				if (step.getTask() != null)
				{
					progress.skip(step.getTask());
				}
				else if (step.getKind() == Step.Kind.SUPPLIES && step.getTarget() != null)
				{
					progress.leprechaunDone();
				}
				else if (step.getKind() == Step.Kind.SUPPLIES)
				{
					progress.suppliesDone();
				}
				refresh(true);
			});
		}

		@Override
		public void bankTab()
		{
			clientThread.invokeLater(() ->
			{
				tabOpened = false;
				Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
				if (bank != null && !bank.isHidden())
				{
					openBankTab();
				}
				else
				{
					tabWanted = true;
					chat("your round's bank tab opens the next time you open your bank.");
				}
			});
		}

		@Override
		public void replan()
		{
			clientThread.invokeLater(() ->
			{
				replan = true;
				roundReplan = progress.isStarted();
				dirty = true;
				refresh(true);
			});
		}
	}
}

package com.codex.rounds.core;

import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/** What the account can use: items it owns, levels, spellbook and travel unlocks. */
public final class Ability
{
	private final Map<Integer, Integer> owned;
	private final Map<Integer, Integer> stored;
	private final Map<String, Integer> paces;
	private final Set<Unlock> unlocks;
	private final boolean unlocksKnown;
	private final boolean bankKnown;
	private final int farming;
	private final int hunter;
	private final int crafting;
	private final int magic;
	private final int spellbook;
	private final boolean fairyRings;

	private Ability(Builder b)
	{
		this.owned = Collections.unmodifiableMap(new HashMap<>(b.owned));
		this.stored = Collections.unmodifiableMap(new HashMap<>(b.stored));
		this.paces = Collections.unmodifiableMap(new HashMap<>(b.paces));
		this.unlocks = b.unlocks == null ? EnumSet.noneOf(Unlock.class) : EnumSet.copyOf(b.unlocks);
		this.unlocksKnown = b.unlocks != null;
		this.bankKnown = b.bankKnown;
		this.farming = b.farming;
		this.hunter = b.hunter;
		this.crafting = b.crafting;
		this.magic = b.magic;
		this.spellbook = b.spellbook;
		this.fairyRings = b.fairyRings;
	}

	public static Builder builder()
	{
		return new Builder();
	}

	/** Everything at 99, owning nothing known: for previews before any data. */
	public static Ability unknown()
	{
		return builder().levels(99, 99, 99, 99).build();
	}

	/** How many of any of these items the account holds across the bank, pack and worn gear. */
	public int count(int... ids)
	{
		int n = 0;
		for (int id : ids)
		{
			n += owned.getOrDefault(id, 0);
		}
		return n;
	}

	/** How many of any of these items the tool leprechaun holds (already part of {@link #count}). */
	public int stored(int... ids)
	{
		int n = 0;
		for (int id : ids)
		{
			n += stored.getOrDefault(id, 0);
		}
		return n;
	}

	/** This player's measured seconds for a teleport leg (see {@link TravelTimer}), or 0 when not yet known. */
	public int pace(String key)
	{
		return paces.getOrDefault(key, 0);
	}

	/** Whether the account owns one; when the bank was never seen, assume it might. */
	public boolean mayOwn(int... ids)
	{
		return !bankKnown || count(ids) > 0;
	}

	public boolean owns(int... ids)
	{
		return count(ids) > 0;
	}

	public boolean isBankKnown()
	{
		return bankKnown;
	}

	public int getFarming()
	{
		return farming;
	}

	public int getHunter()
	{
		return hunter;
	}

	public int getCrafting()
	{
		return crafting;
	}

	public int getMagic()
	{
		return magic;
	}

	public int getSpellbook()
	{
		return spellbook;
	}

	public boolean hasFairyRings()
	{
		return fairyRings;
	}

	/** Whether a way of travelling is open to this account. */
	public boolean canUse(Leg leg)
	{
		// Before quests were ever read, assume the unlock is there rather than hide every route.
		if (leg.getRequires() != null && unlocksKnown && !unlocks.contains(leg.getRequires()))
		{
			return false;
		}
		switch (leg.getKind())
		{
			case ITEM:
				return mayOwn(leg.getItems());
			case SPELL:
				return magic >= leg.getMagicLevel() && spellbook == leg.getSpellbook();
			case FAIRY_RING:
				return fairyRings;
			default:
				return true;
		}
	}

	public static final class Builder
	{
		private final Map<Integer, Integer> owned = new HashMap<>();
		private final Map<Integer, Integer> stored = new HashMap<>();
		private final Map<String, Integer> paces = new HashMap<>();
		private Set<Unlock> unlocks;
		private boolean bankKnown;
		private int farming = 1;
		private int hunter = 1;
		private int crafting = 1;
		private int magic = 1;
		private int spellbook;
		private boolean fairyRings;

		public Builder item(int id, int qty)
		{
			if (id >= 0 && qty > 0)
			{
				owned.merge(id, qty, Integer::sum);
			}
			return this;
		}

		public Builder items(Map<Integer, Integer> items)
		{
			if (items != null)
			{
				items.forEach(this::item);
			}
			return this;
		}

		/** Tools and compost with the tool leprechaun; they count as owned too. */
		public Builder stored(Map<Integer, Integer> items)
		{
			if (items != null)
			{
				items.forEach((id, qty) ->
				{
					if (qty > 0)
					{
						stored.merge(id, qty, Integer::sum);
						item(id, qty);
					}
				});
			}
			return this;
		}

		/** The unlocks the account has, or null when they were never read. */
		public Builder unlocks(Set<Unlock> unlocks)
		{
			this.unlocks = unlocks == null ? null : EnumSet.copyOf(unlocks.isEmpty() ? EnumSet.noneOf(Unlock.class) : unlocks);
			return this;
		}

		public Builder paces(Map<String, Integer> paces)
		{
			if (paces != null)
			{
				this.paces.putAll(paces);
			}
			return this;
		}

		public Builder bankKnown(boolean known)
		{
			this.bankKnown = known;
			return this;
		}

		public Builder levels(int farming, int hunter, int crafting, int magic)
		{
			this.farming = farming;
			this.hunter = hunter;
			this.crafting = crafting;
			this.magic = magic;
			return this;
		}

		public Builder spellbook(int spellbook)
		{
			this.spellbook = spellbook;
			return this;
		}

		public Builder fairyRings(boolean fairyRings)
		{
			this.fairyRings = fairyRings;
			return this;
		}

		public Ability build()
		{
			return new Ability(this);
		}
	}
}

package com.codex.rounds.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The round's pull list as a bank tab: each kind of supply (teleports, tools, seeds, compost and so on) starts a
 * fresh row of the bank's eight columns, in the order the list shows them, so the withdraw is a sweep down the tab.
 */
public final class BankTab
{
	public static final int COLUMNS = 8;

	private BankTab()
	{
	}

	/** Bank positions to item ids, -1 for a gap. Each line shows the variant the bank holds, else the first. */
	public static int[] layout(List<Need> pulls, Map<Integer, Integer> bank)
	{
		List<Integer> out = new ArrayList<>();
		Need.Kind kind = null;
		for (Need n : pulls)
		{
			if (n.getKind() != kind && kind != null)
			{
				while (out.size() % COLUMNS != 0)
				{
					out.add(-1);
				}
			}
			kind = n.getKind();
			int show = n.getItemId();
			for (int id : n.getItems())
			{
				if (bank.getOrDefault(id, 0) > 0)
				{
					show = id;
					break;
				}
			}
			if (show >= 0 && !out.contains(show))
			{
				out.add(show);
			}
		}
		int[] a = new int[out.size()];
		for (int i = 0; i < a.length; i++)
		{
			a[i] = out.get(i);
		}
		return a;
	}

	/** Every item that answers some line, so any variant in the bank shows in the tab. */
	public static Set<Integer> items(List<Need> pulls)
	{
		Set<Integer> out = new LinkedHashSet<>();
		for (Need n : pulls)
		{
			Arrays.stream(n.getItems()).forEach(out::add);
		}
		return out;
	}
}

package com.codex.rounds.core;

import net.runelite.api.gameval.ItemID;

/**
 * Bird house spaces on Fossil Island. The space's player variable is 0 when empty, and otherwise
 * encodes the house type and whether it has seeds: (type * 3) + 1 built, + 3 seeded (RuneLite's
 * BirdHouseState). Seeded houses fill up 50 minutes after the seeds go in.
 */
public final class Birdhouse
{
	public static final int FILL_SECONDS = 50 * 60;
	public static final int SEEDS_PER_HOUSE = 10;

	/** Seeds a bird house takes, any one kind, ten at a time. */
	public static final int[] SEEDS = {
		ItemID.BARLEY_SEED, ItemID.HAMMERSTONE_HOP_SEED, ItemID.ASGARNIAN_HOP_SEED, ItemID.JUTE_SEED,
		ItemID.YANILLIAN_HOP_SEED, ItemID.KRANDORIAN_HOP_SEED, ItemID.WILDBLOOD_HOP_SEED,
	};

	public enum State
	{
		EMPTY,
		BUILT,
		SEEDED,
		UNKNOWN
	}

	public enum Type
	{
		NORMAL("Bird house", ItemID.BIRDHOUSE_NORMAL, ItemID.LOGS, 5, 5),
		OAK("Oak bird house", ItemID.BIRDHOUSE_OAK, ItemID.OAK_LOGS, 14, 15),
		WILLOW("Willow bird house", ItemID.BIRDHOUSE_WILLOW, ItemID.WILLOW_LOGS, 24, 25),
		TEAK("Teak bird house", ItemID.BIRDHOUSE_TEAK, ItemID.TEAK_LOGS, 34, 35),
		MAPLE("Maple bird house", ItemID.BIRDHOUSE_MAPLE, ItemID.MAPLE_LOGS, 44, 45),
		MAHOGANY("Mahogany bird house", ItemID.BIRDHOUSE_MAHOGANY, ItemID.MAHOGANY_LOGS, 49, 50),
		YEW("Yew bird house", ItemID.BIRDHOUSE_YEW, ItemID.YEW_LOGS, 59, 60),
		MAGIC("Magic bird house", ItemID.BIRDHOUSE_MAGIC, ItemID.MAGIC_LOGS, 74, 75),
		REDWOOD("Redwood bird house", ItemID.BIRDHOUSE_REDWOOD, ItemID.REDWOOD_LOGS, 89, 90);

		private final String name;
		private final int itemId;
		private final int logId;
		private final int hunterLevel;
		private final int craftingLevel;

		Type(String name, int itemId, int logId, int hunterLevel, int craftingLevel)
		{
			this.name = name;
			this.itemId = itemId;
			this.logId = logId;
			this.hunterLevel = hunterLevel;
			this.craftingLevel = craftingLevel;
		}

		public String getName()
		{
			return name;
		}

		public int getItemId()
		{
			return itemId;
		}

		public int getLogId()
		{
			return logId;
		}

		public int getHunterLevel()
		{
			return hunterLevel;
		}

		public int getCraftingLevel()
		{
			return craftingLevel;
		}

		/** The best house a Hunter level can place. */
		public static Type bestFor(int hunter)
		{
			Type best = NORMAL;
			for (Type t : values())
			{
				if (t.hunterLevel <= hunter)
				{
					best = t;
				}
			}
			return best;
		}

		public static Type forItem(int itemId)
		{
			for (Type t : values())
			{
				if (t.itemId == itemId)
				{
					return t;
				}
			}
			return null;
		}
	}

	private Birdhouse()
	{
	}

	public static State state(int varp)
	{
		if (varp == 0)
		{
			return State.EMPTY;
		}
		if (varp < 0 || varp > Type.values().length * 3)
		{
			return State.UNKNOWN;
		}
		return varp % 3 == 0 ? State.SEEDED : State.BUILT;
	}

	public static Type type(int varp)
	{
		if (varp <= 0 || varp > Type.values().length * 3)
		{
			return null;
		}
		return Type.values()[(varp - 1) / 3];
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.PatchKind;
import com.codex.rounds.core.farming.Produce;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/** Every chore a round covers and where each one stands. */
public final class Board
{
	public enum Type
	{
		SPOT,
		DAILY,
		KINGDOM
	}

	public static final class Entry
	{
		private final Type type;
		private final Spot spot;
		private final Daily daily;
		private final Status status;
		private final String title;
		private final String detail;
		private final long readyAt;
		private final int itemId;
		private final Reading reading;

		Entry(Type type, Spot spot, Daily daily, Status status, String title, String detail, long readyAt, int itemId, Reading reading)
		{
			this.type = type;
			this.spot = spot;
			this.daily = daily;
			this.status = status;
			this.title = title;
			this.detail = detail;
			this.readyAt = readyAt;
			this.itemId = itemId;
			this.reading = reading;
		}

		public Type getType()
		{
			return type;
		}

		public Spot getSpot()
		{
			return spot;
		}

		public Daily getDaily()
		{
			return daily;
		}

		public Status getStatus()
		{
			return status;
		}

		public String getTitle()
		{
			return title;
		}

		public String getDetail()
		{
			return detail;
		}

		public long getReadyAt()
		{
			return readyAt;
		}

		public int getItemId()
		{
			return itemId;
		}

		/** The spot's reading, or null for dailies and the kingdom. */
		public Reading getReading()
		{
			return reading;
		}

		public Place getPlace()
		{
			switch (type)
			{
				case SPOT:
					return spot.getPlace();
				case DAILY:
					return daily.getPlace();
				default:
					return Place.MISCELLANIA;
			}
		}
	}

	private final List<Entry> entries;
	private final Kingdom kingdom;
	private final long now;

	private Board(List<Entry> entries, Kingdom kingdom, long now)
	{
		this.entries = Collections.unmodifiableList(entries);
		this.kingdom = kingdom;
		this.now = now;
	}

	public List<Entry> getEntries()
	{
		return entries;
	}

	/** The kingdom as known, or null when Throne of Miscellania isn't done or never seen. */
	public Kingdom getKingdom()
	{
		return kingdom;
	}

	public long getNow()
	{
		return now;
	}

	public long count(Status s)
	{
		return entries.stream().filter(e -> e.status == s).count();
	}

	/** The next thing that becomes ready, or null. */
	public Entry nextUp()
	{
		return entries.stream()
			.filter(e -> e.status == Status.GROWING && e.readyAt > now)
			.min(Comparator.comparingLong(Entry::getReadyAt))
			.orElse(null);
	}

	/** A wait worth making: how long, how many more chores it adds, and which groups they are. */
	public static final class Forecast
	{
		private final long waitSeconds;
		private final int more;
		private final List<String> groups;

		Forecast(long waitSeconds, int more, List<String> groups)
		{
			this.waitSeconds = waitSeconds;
			this.more = more;
			this.groups = groups;
		}

		public long getWaitSeconds()
		{
			return waitSeconds;
		}

		public int getMore()
		{
			return more;
		}

		public List<String> getGroups()
		{
			return groups;
		}
	}

	/** How far ahead a wait is worth suggesting. */
	static final long FORECAST_HORIZON = 45 * 60;

	/**
	 * Whether waiting a little brings enough chores in to be worth it: the moment within the horizon that adds the
	 * most chores for each minute waited, when it adds at least two. Minutes are padded by ten so a wait of one
	 * minute for one chore does not beat a wait of fifteen for six.
	 *
	 * @param after only chores ready later than this count, so ones already in the round are not counted twice
	 */
	public Forecast forecast(long after)
	{
		List<Entry> coming = new ArrayList<>();
		for (Entry e : entries)
		{
			if (e.status == Status.GROWING && e.readyAt > Math.max(now, after) && e.readyAt <= now + FORECAST_HORIZON)
			{
				coming.add(e);
			}
		}
		coming.sort(Comparator.comparingLong(Entry::getReadyAt));
		Forecast best = null;
		double bestRate = 0;
		for (int i = 0; i < coming.size(); i++)
		{
			// Several chores often come ready on the same tick; take them all.
			if (i + 1 < coming.size() && coming.get(i + 1).readyAt == coming.get(i).readyAt)
			{
				continue;
			}
			int more = i + 1;
			long wait = coming.get(i).readyAt - now;
			double rate = more / (wait / 60.0 + 10);
			if (more >= 2 && rate > bestRate)
			{
				List<String> groups = new ArrayList<>();
				for (Entry e : coming.subList(0, more))
				{
					String g = e.spot != null ? e.spot.getGroup().getLabel().toLowerCase() : "dailies";
					if (!groups.contains(g))
					{
						groups.add(g);
					}
				}
				best = new Forecast(wait, more, groups);
				bestRate = rate;
			}
		}
		return best;
	}

	/**
	 * Builds the board.
	 *
	 * @param seen    the last value seen for each spot
	 * @param dailies today's dailies, or empty when nothing is known
	 * @param kingdom the kingdom today, or null
	 */
	public static Board build(Map<Spot, Seen> seen, List<DailyState> dailies, Kingdom kingdom, Settings settings,
		Ability ability, long now, Growth.Offset offset)
	{
		List<Entry> list = new ArrayList<>();
		for (Spot spot : Spot.values())
		{
			Reading r = Growth.read(spot, seen.get(spot), now, offset);
			if (!settings.wants(spot))
			{
				r = r.as(Status.OFF, "Left out of rounds");
			}
			else if (r.getStatus() == Status.UNSEEN)
			{
				int need = requiredLevel(spot);
				if (spot.isBirdhouse() ? ability.getHunter() < need : ability.getFarming() < need)
				{
					r = r.as(Status.LOCKED, "Needs " + need + (spot.isBirdhouse() ? " Hunter" : " Farming"));
				}
				else if (!settings.isIncludeUnseen())
				{
					r = r.as(Status.OFF, "Not seen yet");
				}
			}
			list.add(new Entry(Type.SPOT, spot, null, r.getStatus(), spot.getTitle(), r.getSummary(), r.getReadyAt(), icon(spot, r), r));
		}

		for (DailyState d : dailies)
		{
			Status s;
			String detail;
			if (!d.isUnlocked())
			{
				s = Status.LOCKED;
				detail = unlockHint(d.getDaily());
			}
			else if (!settings.wants(d.getDaily()))
			{
				s = Status.OFF;
				detail = "Left out of rounds";
			}
			else if (d.isClaimable())
			{
				s = Status.READY;
				detail = d.getReward();
			}
			else
			{
				s = Status.DONE;
				detail = "Claimed today";
			}
			long reset = (now / 86400 + 1) * 86400;
			list.add(new Entry(Type.DAILY, null, d.getDaily(), s, d.getDaily().getLabel(), detail, s == Status.DONE ? reset : 0, d.getDaily().getItemId(), null));
		}

		if (kingdom != null)
		{
			Status s;
			String detail = kingdom.approvalPercent() + "% approval, " + Format.coins(kingdom.getCoffer()) + " in the coffer"
				+ (kingdom.isEstimated() ? " (estimated)" : "");
			if (!settings.isKingdom())
			{
				s = Status.OFF;
			}
			else if (kingdom.needsVisit(settings.getApprovalTarget(), settings.getCofferTarget(), settings.getTopUpSlack()))
			{
				s = Status.READY;
			}
			else
			{
				s = Status.DONE;
			}
			list.add(new Entry(Type.KINGDOM, null, null, s, "Kingdom of Miscellania", detail, 0, ItemID.POH_TREASURE_TEAK, null));
		}
		return new Board(list, kingdom, now);
	}

	static String unlockHint(Daily d)
	{
		switch (d)
		{
			case ZAFF:
				return "Needs the easy Varrock diary";
			case CROMPERTY:
				return "Needs the medium Ardougne diary";
			case FLAX:
				return "Needs the easy Kandarin diary";
			case RANTZ:
				return "Needs the easy Western Provinces diary";
			case ROBIN:
				return "Needs the medium Morytania diary";
			case THIRUS:
				return "Needs the medium Kourend & Kebos diary";
			case BERT:
				return "Needs The Hand in the Sand";
			case HERB_BOXES:
				return "Needs 9,500 Nightmare Zone points (not for ironmen)";
			case LUNDAIL:
				return "Needs the easy Wilderness diary";
			case CONTRACT:
				return "Talk to Guildmaster Jane in the Farming Guild (45 Farming)";
			default:
				return "Locked";
		}
	}

	/** The lowest level that opens a spot. */
	public static int requiredLevel(Spot spot)
	{
		switch (spot)
		{
			case CELASTRUS_GUILD:
			case REDWOOD_GUILD:
				return 85;
			case SPIRIT_GUILD:
			case ANIMA_GUILD:
			case HESPORI_GUILD:
				return 65;
			case BUSH_GUILD:
			case CACTUS_GUILD:
				return 45;
			default:
				break;
		}
		if (spot.isBirdhouse())
		{
			return 5;
		}
		PatchKind kind = spot.getKind();
		int min = 99;
		for (Produce p : Produce.forKind(kind))
		{
			min = Math.min(min, p.getLevel());
		}
		return min;
	}

	static int icon(Spot spot, Reading r)
	{
		if (spot.isBirdhouse())
		{
			Birdhouse.Type t = r.getSeen() == null ? null : Birdhouse.type(r.getSeen().getValue());
			return t == null ? ItemID.BIRDHOUSE_NORMAL : t.getItemId();
		}
		Produce p = r.getProduce();
		if (p != null)
		{
			return p.getItemId();
		}
		List<Produce> all = Produce.forKind(spot.getKind());
		return all.isEmpty() ? -1 : all.get(all.size() - 1).getItemId();
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.Produce;
import net.runelite.api.gameval.VarbitID;

/**
 * Guildmaster Jane's farming contracts. The contract's crop is a varbit whose values follow RuneLite's Time Tracking
 * plugin; the guild patches Rounds tends (bush, cactus, celastrus, redwood) are planted with the contract crop.
 */
public final class Contract
{
	private static final String[] NAMES = new String[52];

	static
	{
		String[] list = {
			"", "Redberry", "Cadavaberry", "Dwellberry", "Jangerberry", "Whiteberry", "Poison ivy",
			"Oak", "Willow", "Maple", "Yew", "Magic",
			"Apple", "Banana", "Orange", "Curry", "Pineapple", "Papaya", "Palm", "Dragonfruit",
			"Guam", "Marrentill", "Tarromin", "Harralander", "Ranarr", "Toadflax", "Irit", "Avantoe", "Kwuarm",
			"Snapdragon", "Cadantine", "Lantadyme", "Dwarf weed", "Torstol",
			"Marigold", "Rosemary", "Nasturtium", "Woad", "Limpwurt", "White lily",
			"Potato", "Onion", "Cabbage", "Tomato", "Sweetcorn", "Strawberry", "Watermelon", "Snape grass",
			"Cactus", "Potato cactus", "Redwood", "Celastrus",
		};
		System.arraycopy(list, 0, NAMES, 0, list.length);
	}

	private Contract()
	{
	}

	public static int type(Vars v)
	{
		return v.varbit(VarbitID.FARMGUILD_CONTRACT_TYPE);
	}

	public static boolean complete(Vars v)
	{
		return v.varbit(VarbitID.FARMGUILD_CONTRACT_COMPLETE) > 0;
	}

	/** Whether the player has ever been offered contracts. */
	public static boolean known(Vars v)
	{
		return v.varbit(VarbitID.FARMGUILD_CONTRACT_DISCUSSED) > 0 || type(v) > 0 || v.varbit(VarbitID.FARMGUILD_CONTRACT_COUNT) > 0;
	}

	/** The crop's name, or null for no contract or an unknown one. */
	public static String cropName(int type)
	{
		return type > 0 && type < NAMES.length ? NAMES[type] : null;
	}

	/** Which guild patch the crop grows in, for the board. */
	public static String patch(int type)
	{
		if (type >= 1 && type <= 6)
		{
			return "bush patch";
		}
		if (type <= 11)
		{
			return "tree patch";
		}
		if (type <= 19)
		{
			return "fruit tree patch";
		}
		if (type <= 33)
		{
			return "herb patch";
		}
		if (type <= 39)
		{
			return "flower patch";
		}
		if (type <= 47)
		{
			return "allotment";
		}
		if (type <= 49)
		{
			return "cactus patch";
		}
		return type == 50 ? "redwood patch" : "celastrus patch";
	}

	/** The crop when it grows in a guild patch Rounds tends, else null. */
	public static Produce produce(int type)
	{
		switch (type)
		{
			case 1:
				return Produce.REDBERRIES;
			case 2:
				return Produce.CADAVABERRIES;
			case 3:
				return Produce.DWELLBERRIES;
			case 4:
				return Produce.JANGERBERRIES;
			case 5:
				return Produce.WHITEBERRIES;
			case 6:
				return Produce.POISON_IVY;
			case 48:
				return Produce.CACTUS;
			case 49:
				return Produce.POTATO_CACTUS;
			case 50:
				return Produce.REDWOOD;
			case 51:
				return Produce.CELASTRUS;
			default:
				return null;
		}
	}
}

package com.codex.rounds.core;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The once-a-day buys and claims a round can pick up. Unlock and claimed checks follow RuneLite's
 * Daily Task Indicator plugin; amounts follow the diary reward tables.
 */
public enum Daily
{
	ZAFF("Zaff's battlestaves", Place.VARROCK, ItemID.BATTLESTAFF, "Buy battlestaves from Zaff", NpcID.ZAFF),
	CROMPERTY("Cromperty's essence", Place.EAST_ARDOUGNE, ItemID.BLANKRUNE_HIGH, "Claim noted essence from Wizard Cromperty",
		NpcID.CROMPERTY_POST_DIARY, NpcID.CROMPERTY_PRE_DIARY),
	FLAX("Flax to bowstrings", Place.SEERS_VILLAGE, ItemID.BOW_STRING, "Hand your flax to the Flax keeper", NpcID.DIARY_FLAX_KEEPER),
	RANTZ("Rantz's ogre arrows", Place.FELDIP_HILLS, ItemID.OGRE_ARROW, "Claim ogre arrows from Rantz",
		NpcID.RANTZ, NpcID._100_RANTZ, NpcID._100_RANTZ1, NpcID._100_RANTZ2),
	ROBIN("Robin's bonemeal and slime", Place.PORT_PHASMATYS, ItemID.POT_BONEMEAL, "Hand your bones to Robin", NpcID.AHOY_ROBIN),
	THIRUS("Thirus's dynamite", Place.LOVAKENGJ, ItemID.LOVAKENGJ_DYNAMITE_FUSED, "Claim dynamite from Thirus",
		NpcID.LOVAKENGJ_THIRUS_POST_DIARY, NpcID.LOVAKENGJ_THIRUS, NpcID.LOVAKENGJ_THIRUS_PRE_DIARY),
	BERT("Bert's sand", Place.YANILLE, ItemID.BUCKET_SAND, "Ask Bert for your sand", NpcID.HANDSAND_BERT_2OPS, NpcID.HANDSAND_BERT_1OP, NpcID.HANDSAND_BERT),
	HERB_BOXES("Herb boxes", Place.NIGHTMARE_ZONE, ItemID.NZONE_HERBBOX, "Buy herb boxes from Dominic Onion", NpcID.NZONE_HOST),
	LUNDAIL("Lundail's runes", Place.MAGE_ARENA, ItemID.DEATHRUNE, "Claim runes from Lundail", NpcID.MAGEARENA_RUNESHOP),
	/** Not daily, but a chore of the same shape: a talk at a place, ready again whenever a contract is done. */
	CONTRACT("Farming contract", Place.FARMING_GUILD, ItemID.SEEDBOX, "Talk to Guildmaster Jane about your contract",
		NpcID.FARMING_GUILD_MASTER, NpcID.FARMING_GUILD_MASTER_1OP, NpcID.FARMING_GUILD_MASTER_2OP);

	public static final int ZAFF_PRICE = 7_000;
	public static final int HERB_BOX_POINTS = 9_500;
	public static final int HERB_BOX_MAX = 15;
	public static final int SAND_QUEST_COMPLETE = 160;
	public static final int ROBIN_PER_TIER = 13;
	/** Robin takes unnoted bones of any kind; the common ones count as packed. */
	static final int[] ROBIN_BONES = {ItemID.BONES, ItemID.BAT_BONES, ItemID.BIG_BONES, ItemID.BABYDRAGON_BONES, ItemID.DRAGON_BONES,
		ItemID.WOLF_BONES, ItemID.ZOGRE_BONES, ItemID.WYVERN_BONES, ItemID.LAVA_DRAGON_BONES};
	public static final int BERT_SAND = 84;

	private final String label;
	private final Place place;
	private final int itemId;
	private final String action;
	private final int[] npcs;

	Daily(String label, Place place, int itemId, String action, int... npcs)
	{
		this.label = label;
		this.place = place;
		this.itemId = itemId;
		this.action = action;
		this.npcs = npcs;
	}

	public String getLabel()
	{
		return label;
	}

	public Place getPlace()
	{
		return place;
	}

	/** The item shown on the board for this daily. */
	public int getItemId()
	{
		return itemId;
	}

	/** What to do at the stop, as a step title. */
	public String getAction()
	{
		return action;
	}

	public int[] getNpcs()
	{
		return npcs.clone();
	}

	public boolean isNpc(int id)
	{
		for (int n : npcs)
		{
			if (n == id)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether it comes back at the daily reset; a contract only comes back when it is done. */
	public boolean resetsDaily()
	{
		return this != CONTRACT;
	}

	/** Whether the account has earned this daily at all. */
	public boolean unlocked(Vars v)
	{
		switch (this)
		{
			case ZAFF:
				return done(v, VarbitID.VARROCK_DIARY_EASY_COMPLETE);
			case CROMPERTY:
				return done(v, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE);
			case FLAX:
				return done(v, VarbitID.KANDARIN_DIARY_EASY_COMPLETE);
			case RANTZ:
				return done(v, VarbitID.WESTERN_DIARY_EASY_COMPLETE);
			case ROBIN:
				return done(v, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE);
			case THIRUS:
				return done(v, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE);
			case BERT:
				return v.varbit(VarbitID.IRONMAN) != 2 && v.varbit(VarbitID.HANDSAND_QUEST) >= SAND_QUEST_COMPLETE;
			case HERB_BOXES:
				return v.varbit(VarbitID.IRONMAN) == 0 && v.varp(VarPlayerID.NZONE_REWARDPOINTS) >= HERB_BOX_POINTS;
			case LUNDAIL:
				return done(v, VarbitID.WILDERNESS_DIARY_EASY_COMPLETE);
			case CONTRACT:
				return Contract.known(v);
			default:
				return false;
		}
	}

	/** Whether today's claim is still waiting. */
	public boolean claimable(Vars v)
	{
		if (!unlocked(v))
		{
			return false;
		}
		switch (this)
		{
			case ZAFF:
				return v.varbit(VarbitID.ZAFF_LAST_CLAIMED) == 0;
			case CROMPERTY:
				return v.varbit(VarbitID.ARDOUGNE_FREE_ESSENCE) == 0;
			case FLAX:
				return v.varbit(VarbitID.SEERS_FREE_FLAX) == 0;
			case RANTZ:
				return v.varbit(VarbitID.WESTERN_RANTZ_ARROWS) == 0;
			case ROBIN:
				return v.varbit(VarbitID.MORYTANIA_SLIME_CLAIMED) < amount(v);
			case THIRUS:
				return v.varbit(VarbitID.KOUREND_FREE_DYNAMITE) == 0;
			case BERT:
				return v.varbit(VarbitID.YANILLE_SAND_CLAIMED) == 0;
			case HERB_BOXES:
				return v.varbit(VarbitID.NZONE_HERBBOXES_PURCHASED) < HERB_BOX_MAX;
			case LUNDAIL:
				return v.varbit(VarbitID.LUNDAIL_LAST_CLAIMED) == 0;
			case CONTRACT:
				return Contract.complete(v) || Contract.type(v) == 0;
			default:
				return false;
		}
	}

	/** How many come today, or 0 when the amount is random. */
	public int amount(Vars v)
	{
		int t;
		switch (this)
		{
			case ZAFF:
				return pick(tier(v, VarbitID.VARROCK_DIARY_EASY_COMPLETE), 15, 30, 60, 120);
			case CROMPERTY:
				t = tier(v, VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE);
				return pick(t, 0, 100, 150, 250);
			case FLAX:
				return pick(tier(v, VarbitID.KANDARIN_DIARY_EASY_COMPLETE), 30, 60, 120, 250);
			case RANTZ:
				return pick(tier(v, VarbitID.WESTERN_DIARY_EASY_COMPLETE), 25, 50, 100, 150);
			case ROBIN:
				t = tier(v, VarbitID.MORYTANIA_DIARY_EASY_COMPLETE);
				return Math.max(0, t - 1) * ROBIN_PER_TIER;
			case THIRUS:
				return pick(tier(v, VarbitID.KOUREND_DIARY_EASY_COMPLETE), 0, 20, 40, 80);
			case BERT:
				return BERT_SAND;
			case HERB_BOXES:
				int left = HERB_BOX_MAX - v.varbit(VarbitID.NZONE_HERBBOXES_PURCHASED);
				return Math.max(0, Math.min(left, v.varp(VarPlayerID.NZONE_REWARDPOINTS) / HERB_BOX_POINTS));
			default:
				return 0;
		}
	}

	/** Robin hands out a share at a time; how many are left today. */
	public int remaining(Vars v)
	{
		if (this == ROBIN)
		{
			return Math.max(0, amount(v) - v.varbit(VarbitID.MORYTANIA_SLIME_CLAIMED));
		}
		return amount(v);
	}

	/** What the board says comes back, such as "120 battlestaves". */
	public String reward(Vars v)
	{
		int n = remaining(v);
		switch (this)
		{
			case ZAFF:
				return n + " battlestaves for " + Format.coins((long) n * ZAFF_PRICE);
			case CROMPERTY:
				return n + " noted pure essence";
			case FLAX:
				return n + " flax spun into bowstrings";
			case RANTZ:
				return n + " ogre arrows";
			case ROBIN:
				return n + " bonemeal and buckets of slime";
			case THIRUS:
				return n + " dynamite";
			case BERT:
				return n + " buckets of sand";
			case HERB_BOXES:
				return n + " herb boxes for " + Format.number((long) n * HERB_BOX_POINTS) + " points";
			case LUNDAIL:
				return "A random handful of runes";
			case CONTRACT:
				int type = Contract.type(v);
				if (Contract.complete(v))
				{
					return "Done: hand it in for a seed pack and take the next";
				}
				if (type == 0 || Contract.cropName(type) == null)
				{
					return "No contract running: take one";
				}
				return Contract.cropName(type) + " in the guild's " + Contract.patch(type)
					+ (Contract.produce(type) != null ? ", planted on your round" : ", on your farm run");
			default:
				return "";
		}
	}

	/** What the player needs to bring for it, or null. */
	public Need need(Vars v)
	{
		int n = remaining(v);
		switch (this)
		{
			case ZAFF:
				return new Need(Need.Kind.COINS, "Coins", n * ZAFF_PRICE, "Zaff's battlestaves", false, ItemID.COINS);
			case FLAX:
				return new Need(Need.Kind.DAILY, "Flax (noted is fine)", n, "the Flax keeper", false, ItemID.FLAX, ItemID.FLAX + 1);
			case ROBIN:
				return new Need(Need.Kind.DAILY, "Bones, unnoted (any kind)", n, "Robin", false, ROBIN_BONES);
			default:
				return null;
		}
	}

	/** Diary tiers done from easy upwards: easy is 1, elite 4. Each tier's varbit follows the last. */
	static int tier(Vars v, int easyVarbit)
	{
		int t = 0;
		for (int i = 0; i < 4; i++)
		{
			if (v.varbit(easyVarbit + i) == 1)
			{
				t = i + 1;
			}
		}
		return t;
	}

	private static int pick(int tier, int... byTier)
	{
		return tier <= 0 ? 0 : byTier[Math.min(tier, byTier.length) - 1];
	}

	private static boolean done(Vars v, int varbit)
	{
		return v.varbit(varbit) == 1;
	}
}

package com.codex.rounds.core;

/** A daily's standing today: unlocked, claimable, what it gives and needs. */
public final class DailyState
{
	private final Daily daily;
	private final boolean unlocked;
	private final boolean claimable;
	private final String reward;
	private final Need need;

	public DailyState(Daily daily, boolean unlocked, boolean claimable, String reward, Need need)
	{
		this.daily = daily;
		this.unlocked = unlocked;
		this.claimable = claimable;
		this.reward = reward;
		this.need = need;
	}

	public static DailyState of(Daily d, Vars v)
	{
		boolean unlocked = d.unlocked(v);
		boolean claimable = unlocked && d.claimable(v);
		return new DailyState(d, unlocked, claimable, unlocked ? d.reward(v) : "", claimable ? d.need(v) : null);
	}

	public Daily getDaily()
	{
		return daily;
	}

	public boolean isUnlocked()
	{
		return unlocked;
	}

	public boolean isClaimable()
	{
		return claimable;
	}

	public String getReward()
	{
		return reward;
	}

	/** What to bring, or null. */
	public Need getNeed()
	{
		return need;
	}

	/** The state after the daily reset: claimable again if it was ever unlocked. */
	public DailyState afterReset()
	{
		return new DailyState(daily, unlocked, unlocked, reward, need);
	}
}

package com.codex.rounds.core;

import java.util.Locale;

/** Text for numbers and times, the way the game writes them. */
public final class Format
{
	private Format()
	{
	}

	public static String number(long n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}

	/** 7,000 / 840k / 1.2m coins. */
	public static String coins(long n)
	{
		return stack(n) + " coins";
	}

	public static String stack(long n)
	{
		if (n >= 10_000_000)
		{
			return (n / 1_000_000) + "m";
		}
		if (n >= 1_000_000)
		{
			return trim(n / 1_000_000.0) + "m";
		}
		if (n >= 100_000)
		{
			return (n / 1000) + "k";
		}
		return number(n);
	}

	private static String trim(double d)
	{
		String s = String.format(Locale.ROOT, "%.1f", d);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}

	/** "now", "4 min", "1 hr 20 min", "2 days 3 hr". */
	public static String duration(long seconds)
	{
		if (seconds <= 0)
		{
			return "now";
		}
		long mins = (seconds + 59) / 60;
		if (mins < 60)
		{
			return mins + " min";
		}
		long hrs = mins / 60;
		long rem = mins % 60;
		if (hrs < 24)
		{
			return rem == 0 ? hrs + " hr" : hrs + " hr " + rem + " min";
		}
		long days = hrs / 24;
		long h = hrs % 24;
		return (days == 1 ? "1 day" : days + " days") + (h == 0 ? "" : " " + h + " hr");
	}

	/** A short duration for tight spaces: "4m", "1h 20m", "2d 3h". */
	public static String shortDuration(long seconds)
	{
		if (seconds <= 0)
		{
			return "now";
		}
		long mins = (seconds + 59) / 60;
		if (mins < 60)
		{
			return mins + "m";
		}
		long hrs = mins / 60;
		long rem = mins % 60;
		if (hrs < 24)
		{
			return rem == 0 ? hrs + "h" : hrs + "h " + rem + "m";
		}
		long days = hrs / 24;
		long h = hrs % 24;
		return h == 0 ? days + "d" : days + "d " + h + "h";
	}

	/** Seconds as m:ss for a round's running clock. */
	public static String clock(long seconds)
	{
		long s = Math.max(0, seconds);
		if (s >= 3600)
		{
			return String.format(Locale.ROOT, "%d:%02d:%02d", s / 3600, (s / 60) % 60, s % 60);
		}
		return String.format(Locale.ROOT, "%d:%02d", s / 60, s % 60);
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.Action;
import com.codex.rounds.core.farming.CropState;
import com.codex.rounds.core.farming.PatchKind;
import com.codex.rounds.core.farming.PatchState;

/**
 * Predicts a patch or bird house from the last time it was seen. Farming ticks land on fixed
 * five-minute marks shifted by an account offset; the maths follows RuneLite's FarmingTracker.
 */
public final class Growth
{
	private Growth()
	{
	}

	/** The account's farming tick offset as RuneLite's Time Tracking learned it, or none. */
	public static final class Offset
	{
		public static final Offset NONE = new Offset(null, null);

		private final Integer minutes;
		private final Integer precision;

		public Offset(Integer minutes, Integer precision)
		{
			this.minutes = minutes;
			this.precision = precision;
		}

		long seconds(int tickRate)
		{
			if (minutes != null && precision != null && (precision >= tickRate || precision >= 40))
			{
				return (long) (minutes % tickRate) * 60;
			}
			return 0;
		}
	}

	private static final java.util.Map<PatchKind, Boolean> HEALTH_CHECK = new java.util.EnumMap<>(PatchKind.class);

	/** Whether a kind of patch has a check-health state once grown; Hespori, for one, goes straight to harvest. */
	static synchronized boolean hasHealthCheck(PatchKind kind)
	{
		return HEALTH_CHECK.computeIfAbsent(kind, k ->
		{
			for (int v = 0; v < 256; v++)
			{
				PatchState s = k.forVarbitValue(v);
				if (s != null && s.getAction() == Action.CHECK_HEALTH)
				{
					return true;
				}
			}
			return false;
		});
	}

	/** The unix second of the tick {@code ticks} after the one {@code time} falls in. */
	public static long tickTime(int tickRate, int ticks, long time, Offset offset)
	{
		long shift = offset.seconds(tickRate);
		long t = time + shift;
		long period = tickRate * 60L;
		long current = t - (t % period);
		return current + ticks * period - shift;
	}

	/** Reads a spot from what was last seen. */
	public static Reading read(Spot spot, Seen seen, long now, Offset offset)
	{
		if (seen == null)
		{
			return Reading.unseen(spot);
		}
		return spot.isBirdhouse() ? readBirdhouse(spot, seen, now) : readPatch(spot, seen, now, offset);
	}

	private static Reading readBirdhouse(Spot spot, Seen seen, long now)
	{
		Birdhouse.State state = Birdhouse.state(seen.getValue());
		switch (state)
		{
			case EMPTY:
				return Reading.birdhouse(spot, seen, Status.READY, state, 0, "Empty space: build a bird house");
			case BUILT:
				return Reading.birdhouse(spot, seen, Status.READY, state, 0, "Built: add seeds");
			case SEEDED:
				long full = seen.getTime() + Birdhouse.FILL_SECONDS;
				return now >= full
					? Reading.birdhouse(spot, seen, Status.READY, state, full, "Full: collect and reset")
					: Reading.birdhouse(spot, seen, Status.GROWING, state, full, "Filling");
			default:
				return Reading.unseen(spot);
		}
	}

	private static Reading readPatch(Spot spot, Seen seen, long now, Offset offset)
	{
		PatchState state = spot.getKind().forVarbitValue(seen.getValue());
		if (state == null)
		{
			return Reading.unseen(spot);
		}

		int stage = state.getStage();
		int stages = state.getStages();
		int tickRate = state.getProduce().getTickrate();
		if (state.getCropState() == CropState.HARVESTABLE)
		{
			tickRate = state.getProduce().getRegrowTickrate();
		}

		if (state.isEmpty())
		{
			// Weeds grow back on their own but nothing is lost: the patch is ready to plant.
			return Reading.patch(spot, seen, Status.READY, state, state.isClear() ? Action.PLANT : Action.RAKE, 0,
				state.isClear() ? "Clear soil: plant it" : "Weeds: rake and plant");
		}

		switch (state.getCropState())
		{
			case DISEASED:
				return Reading.patch(spot, seen, Status.READY, state, state.getAction(), 0, "Diseased: cure it");
			case DEAD:
				return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, 0,
					state.getStage() == 0 && state.getAction() == Action.CLEAR ? "Stump: clear and replant" : "Dead: clear and replant");
			case HARVESTABLE:
				if (state.getAction() == Action.CHOP)
				{
					return Reading.patch(spot, seen, Status.READY, state, Action.CHOP, 0, "Grown: clear and replant");
				}
				if (state.getAction() == Action.CLEAR)
				{
					return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, 0, "Stump: clear and replant");
				}
				if (spot.getKind() == PatchKind.CALQUAT && stage == 0)
				{
					return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, 0, "Picked: dig it up and replant");
				}
				if (tickRate > 0)
				{
					// Berries and spines grow back a stage at a time; stop when the bush is full.
					long seenTick = tickTime(tickRate, 0, seen.getTime(), offset);
					long nowTick = tickTime(tickRate, 0, now, offset);
					int delta = (int) ((nowTick - seenTick) / (tickRate * 60L));
					long full = tickTime(tickRate, stages - 1 - stage, seenTick, offset);
					return stage + delta >= stages - 1
						? Reading.patch(spot, seen, Status.READY, state, Action.HARVEST, full, "Full: ready to pick")
						: Reading.patch(spot, seen, Status.GROWING, state, Action.WAIT, full, "Regrowing");
				}
				return Reading.patch(spot, seen, Status.READY, state, Action.HARVEST, 0, "Ready to harvest");
			case GROWING:
			default:
				break;
		}

		if (state.getAction() == Action.GROWN)
		{
			return Reading.patch(spot, seen, Status.DONE, state, Action.GROWN, 0, "Fully grown");
		}
		if (state.getAction() == Action.CHECK_HEALTH)
		{
			return Reading.patch(spot, seen, Status.READY, state, Action.CHECK_HEALTH, 0, "Ready: check its health");
		}
		if (tickRate <= 0)
		{
			return Reading.patch(spot, seen, Status.GROWING, state, Action.WAIT, 0, "Growing");
		}

		long seenTick = tickTime(tickRate, 0, seen.getTime(), offset);
		long nowTick = tickTime(tickRate, 0, now, offset);
		int delta = (int) ((nowTick - seenTick) / (tickRate * 60L));
		long done = tickTime(tickRate, stages - 1 - stage, seenTick, offset);
		boolean anima = spot.getKind() == PatchKind.ANIMA;
		if (stage + delta >= stages - 1)
		{
			if (anima)
			{
				return Reading.patch(spot, seen, Status.READY, state, Action.CLEAR, done, "Withered: clear and replant");
			}
			Action next = hasHealthCheck(spot.getKind()) ? Action.CHECK_HEALTH : Action.HARVEST;
			return Reading.patch(spot, seen, Status.READY, state, next, done,
				next == Action.CHECK_HEALTH ? "Ready: check its health" : "Ready to harvest");
		}
		return Reading.patch(spot, seen, Status.GROWING, state, Action.WAIT, done, anima ? "Active" : "Growing");
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.Action;
import com.codex.rounds.core.farming.PatchKind;
import com.codex.rounds.core.farming.Produce;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * Works out the single next step of a round from what the game shows right now. It holds no
 * state: the round's plan, the live readings and the little the game doesn't show (compost,
 * payments, skips) go in, and one step comes out, so it can never drift out of step.
 */
public final class Guide
{
	static final int[] COMPOST = {ItemID.BUCKET_ULTRACOMPOST, ItemID.BUCKET_SUPERCOMPOST, ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED};

	private Guide()
	{
	}

	/** The game as it is this tick. */
	public static final class World
	{
		final Point player;
		final Map<Spot, Reading> live;
		final Map<Daily, DailyState> dailies;
		final Kingdom kingdom;
		final Map<Integer, Integer> carried;
		final Ability ability;
		final long now;

		public World(Point player, Map<Spot, Reading> live, Map<Daily, DailyState> dailies, Kingdom kingdom,
			Map<Integer, Integer> carried, Ability ability, long now)
		{
			this.player = player;
			this.live = live;
			this.dailies = dailies;
			this.kingdom = kingdom;
			this.carried = carried;
			this.ability = ability;
			this.now = now;
		}

		int carrying(int... ids)
		{
			int n = 0;
			for (int id : ids)
			{
				n += carried.getOrDefault(id, 0);
			}
			return n;
		}
	}

	/** Whether a chore is finished, from the live game. */
	public static boolean isDone(Task t, World w, Progress progress, Settings settings, long since)
	{
		if (progress.isSkipped(t))
		{
			return true;
		}
		switch (t.getType())
		{
			case DAILY:
				DailyState d = w.dailies.get(t.getDaily());
				return d != null && !d.isClaimable();
			case KINGDOM:
				return w.kingdom != null && !w.kingdom.needsVisit(settings.getApprovalTarget(), settings.getCofferTarget(), settings.getTopUpSlack());
			default:
				break;
		}
		Spot spot = t.getSpot();
		Reading r = w.live.get(spot);
		Reading planned = t.getReading();
		if (r == null || r.getStatus() == Status.UNSEEN)
		{
			return false;
		}
		if (spot.isBirdhouse())
		{
			if (r.getHouse() != Birdhouse.State.SEEDED)
			{
				return false;
			}
			return r.getSeen().getTime() >= since || (planned.getStatus() == Status.UNSEEN && r.getStatus() == Status.GROWING);
		}
		if (r.getStatus() == Status.READY)
		{
			// Nothing was meant to go in: an empty patch is as far as this round takes it.
			return t.getPlant() == null && (r.getAction() == Action.PLANT || r.getAction() == Action.RAKE);
		}
		if (r.getStatus() == Status.GROWING && !progress.wasPlanted(spot) && !progress.wasSeenReady(spot))
		{
			// Growing without being seen ready or replanted this round: it came early, or the prediction ran ahead.
			return false;
		}
		if (progress.wasPlanted(spot))
		{
			if (t.isCompost() && !progress.isComposted(spot))
			{
				return false;
			}
			if (t.isProtect() && !progress.isPaid(spot))
			{
				return false;
			}
		}
		return true;
	}

	public static Step next(Route route, World w, Progress progress, Settings settings)
	{
		if (route == null || route.isEmpty())
		{
			return Step.IDLE;
		}
		long since = progress.isStarted() ? progress.getStartedAt() : route.getBuiltAt();
		noteReady(route, w, progress, since);
		int total = route.taskCount();
		int done = 0;
		int current = -1;
		for (int i = 0; i < route.getStops().size(); i++)
		{
			Stop s = route.getStops().get(i);
			int left = 0;
			for (Task t : s.getTasks())
			{
				if (isDone(t, w, progress, settings, since))
				{
					done++;
				}
				else
				{
					left++;
				}
			}
			if (left > 0 && current < 0)
			{
				current = i;
			}
		}
		if (current < 0)
		{
			return new Step(Step.Kind.IDLE, "Round complete", "Every stop is done. Nice work.", null, Collections.emptyList(), null, null,
				-1, done, total);
		}

		Stop stop = route.getStops().get(current);
		if (done == 0 && current == 0 && !progress.isSuppliesDone() && !stop.getPlace().contains(w.player))
		{
			List<Need> missing = missing(route, w);
			if (!missing.isEmpty())
			{
				List<Integer> ids = new ArrayList<>();
				StringBuilder b = new StringBuilder();
				for (Need n : missing)
				{
					ids.add(n.getItemId());
					if (b.length() > 0)
					{
						b.append(", ");
					}
					b.append(n.getQuantity() > 1 ? Format.number(n.getQuantity()) + " x " : "").append(n.getLabel().toLowerCase());
				}
				return new Step(Step.Kind.SUPPLIES, "Get your supplies", "Still to withdraw: " + b, null, ids, null, null, current, done, total);
			}
		}

		Place place = stop.getPlace();
		if (!place.contains(w.player))
		{
			return travel(stop, place, w, current, done, total);
		}

		if (Leprechaun.PLACES.contains(place) && !progress.isLeprechaunDone())
		{
			List<Need> take = fromLeprechaun(route.getPulls(), w);
			if (!take.isEmpty())
			{
				List<Integer> ids = new ArrayList<>();
				StringBuilder b = new StringBuilder();
				for (Need n : take)
				{
					ids.add(n.getItemId());
					if (b.length() > 0)
					{
						b.append(", ");
					}
					b.append(n.getQuantity() > 1 ? Format.number(n.getQuantity()) + " x " : "").append(n.getLabel().toLowerCase());
				}
				return new Step(Step.Kind.SUPPLIES, "Take tools from the leprechaun", "Stored with him: " + b,
					Step.Target.npc(place.getAnchor(), Leprechaun.NPCS), ids, null, null, current, done, total);
			}
		}

		Task task = nearest(stop, w, progress, settings, since);
		return taskStep(task, w, progress, current, done, total);
	}

	/** Marks spots a fresh reading shows ready, so a harvest that leaves them growing again counts as done. */
	static void noteReady(Route route, World w, Progress progress, long since)
	{
		for (Stop s : route.getStops())
		{
			for (Task t : s.getTasks())
			{
				Spot spot = t.getSpot();
				Reading r = spot == null ? null : w.live.get(spot);
				if (r != null && r.getStatus() == Status.READY && r.getSeen() != null && r.getSeen().getTime() >= since)
				{
					progress.sawReady(spot);
				}
			}
		}
	}

	static Step travel(Stop stop, Place place, World w, int current, int done, int total)
	{
		Place via = place.getVia();
		if (via != null && via.contains(w.player))
		{
			Step.Target target = place.getLocalObject() >= 0
				? Step.Target.object(place.getLocalPoint(), place.getLocalObject())
				: Step.Target.tile(place.getLocalPoint());
			return new Step(Step.Kind.TRAVEL, place.getLocalStep(), "On to " + place.getLabel() + ": " + place.getDetail(), target,
				Collections.emptyList(), place.getLocalPoint(), null, current, done, total);
		}
		Travel.Way way = Travel.best(w.player, place, w.ability);
		Place landing = way.getPlace();
		String detail = (landing != place ? landing.getLabel() + ", then " + place.getLocalStep().toLowerCase() : place.getLabel() + ": " + place.getDetail());
		Leg leg = way.getLeg();
		if (leg == null)
		{
			return new Step(Step.Kind.TRAVEL, "Walk to " + landing.getLabel(), detail, Step.Target.tile(landing.getAnchor()),
				Collections.emptyList(), landing.getAnchor(), null, current, done, total);
		}
		List<Integer> items = new ArrayList<>();
		String title;
		switch (leg.getKind())
		{
			case ITEM:
				items.addAll(owned(leg.getItems(), w.ability));
				title = leg.getLabel();
				break;
			case SPELL:
				title = "Cast " + leg.getLabel();
				break;
			case FAIRY_RING:
				title = leg.getLabel();
				detail = "Dial " + leg.getLabel().replace("Fairy ring ", "") + " for " + detail;
				items.addAll(owned(Teleports.FAIRY_STAFFS, w.ability));
				break;
			default:
				title = leg.getLabel();
				break;
		}
		return new Step(Step.Kind.TRAVEL, title, detail, null, items, landing.getAnchor(), null, current, done, total);
	}

	/** The variants the player has, so the card shows one item, not every version of it. */
	static List<Integer> owned(int[] ids, Ability ability)
	{
		List<Integer> out = new ArrayList<>();
		for (int id : ids)
		{
			if (ability.owns(id))
			{
				out.add(id);
			}
		}
		if (out.isEmpty() && ids.length > 0)
		{
			out.add(ids[0]);
		}
		return out;
	}

	/** The closest unfinished chore at the stop, so the player never doubles back. */
	static Task nearest(Stop stop, World w, Progress progress, Settings settings, long since)
	{
		Task best = null;
		int bestDist = Integer.MAX_VALUE;
		for (Task t : stop.getTasks())
		{
			if (isDone(t, w, progress, settings, since))
			{
				continue;
			}
			Point p = where(t);
			int d = p == null || w.player == null ? 0 : p.distance(w.player);
			if (best == null || d < bestDist)
			{
				best = t;
				bestDist = d;
			}
		}
		return best;
	}

	static Point where(Task t)
	{
		switch (t.getType())
		{
			case SPOT:
				return t.getSpot().getPoint();
			case DAILY:
				return t.getDaily().getPlace().getAnchor();
			default:
				return Place.MISCELLANIA.getAnchor();
		}
	}

	static Step taskStep(Task t, World w, Progress progress, int current, int done, int total)
	{
		switch (t.getType())
		{
			case DAILY:
				Daily d = t.getDaily();
				Point near = d.getPlace().getAnchor();
				List<Integer> items = new ArrayList<>();
				DailyState ds = w.dailies.get(d);
				if (ds != null && ds.getNeed() != null)
				{
					items.add(ds.getNeed().getItemId());
				}
				return new Step(Step.Kind.TASK, d.getAction(), t.getDetail(), Step.Target.npc(near, d.getNpcs()), items, near, t, current, done, total);
			case KINGDOM:
				return kingdomStep(t, w, current, done, total);
			default:
				return spotStep(t, w, progress, current, done, total);
		}
	}

	static Step kingdomStep(Task t, World w, int current, int done, int total)
	{
		Kingdom k = w.kingdom;
		Point ghrim = Place.MISCELLANIA.getAnchor();
		if (k != null && t.getDetail().toLowerCase().contains("deposit") && k.getCoffer() < Kingdom.MAX_COFFER)
		{
			return new Step(Step.Kind.TASK, "Top up the coffer", "Talk to Advisor Ghrim and choose to deposit coins. " + t.getDetail() + ".",
				Step.Target.npc(ghrim, 5447, 5448, 3670), Collections.singletonList(ItemID.COINS), ghrim, t, current, done, total);
		}
		String pct = k == null ? "" : " (now " + k.approvalPercent() + "%)";
		return new Step(Step.Kind.TASK, "Raise approval" + pct,
			"Chop maples, mine coal, fish or rake herbs on Miscellania until approval is full, then collect from Advisor Ghrim.",
			null, Collections.emptyList(), ghrim, t, current, done, total);
	}

	static Step spotStep(Task t, World w, Progress progress, int current, int done, int total)
	{
		Spot spot = t.getSpot();
		Reading r = w.live.get(spot);
		Point at = spot.getPoint();
		Step.Target here = Step.Target.spot(spot);
		if (r == null || r.getStatus() == Status.UNSEEN)
		{
			return task(t, "Look at the " + spot.kindName().toLowerCase(), spot.getLabel() + ": walk up to it so the round can read it.", here, at,
				current, done, total);
		}

		if (spot.isBirdhouse())
		{
			Birdhouse.State st = r.getHouse();
			if (st == Birdhouse.State.SEEDED && r.getStatus() == Status.READY)
			{
				return task(t, "Empty the bird house", spot.getLabel() + ": collect the catch.", here, at, current, done, total);
			}
			if (st == Birdhouse.State.SEEDED)
			{
				return task(t, "Wait for the bird house", "Full in " + Format.duration(r.secondsLeft(w.now)) + ".", here, at, current, done, total);
			}
			if (st == Birdhouse.State.BUILT)
			{
				return task(t, "Add ten seeds", "Use hop seeds on the bird house.", here, at, current, done, total, Birdhouse.SEEDS);
			}
			Birdhouse.Type type = Supplies.houseType(w.ability);
			int[] houses = carriedHouses(w);
			if (houses.length > 0)
			{
				Birdhouse.Type have = Birdhouse.Type.forItem(houses[0]);
				return task(t, "Build the bird house", "Click the space to set up your " + have.getName().toLowerCase() + ".", here, at, current, done, total,
					houses);
			}
			return task(t, "Craft a bird house", "Use a chisel on your " + Supplies.logName(type).toLowerCase()
				+ " with clockwork in your pack, then build it on the space.", here, at, current, done, total, ItemID.CHISEL, type.getLogId());
		}

		String where = spot.getLabel();
		PatchKind kind = spot.getKind();
		Produce plant = t.getPlant();
		if (r.getStatus() == Status.GROWING || r.getStatus() == Status.DONE)
		{
			if (progress.wasPlanted(spot) && t.isCompost() && !progress.isComposted(spot))
			{
				return task(t, "Compost the patch", where + ": use your compost on it.", here, at, current, done, total, COMPOST);
			}
			if (progress.wasPlanted(spot) && t.isProtect() && !progress.isPaid(spot) && plant != null)
			{
				int[] pay = plant.getPayment();
				int[] ids = new int[pay.length];
				StringBuilder b = new StringBuilder();
				for (int i = 0; i + 1 < pay.length; i += 2)
				{
					ids[i] = pay[i];
					ids[i + 1] = pay[i] + 1;
					if (b.length() > 0)
					{
						b.append(", ");
					}
					b.append(pay[i + 1]).append(' ').append(Supplies.itemName(pay[i]).toLowerCase());
				}
				return task(t, "Pay the gardener", "Talk to the gardener and pay " + b + " to protect it.",
					Step.Target.npc(at, spot.getGardener()), at, current, done, total, ids);
			}
			long left = r.secondsLeft(w.now);
			return task(t, "Not ready yet", where + ": ready in " + Format.duration(left) + ". Wait, or skip it this round.", here, at,
				current, done, total);
		}

		Action a = r.getAction();
		if (a == null)
		{
			a = Action.WAIT;
		}
		switch (a)
		{
			case RAKE:
				return task(t, "Rake the patch", where + (plant == null ? "" : ": then plant " + Planner.seedName(plant) + "."), here, at,
					current, done, total, ItemID.RAKE);
			case PLANT:
				if (plant == null)
				{
					return task(t, "Leave it empty", where + ": nothing chosen to plant. Skip it.", here, at, current, done, total);
				}
				return task(t, "Plant " + Planner.seedName(plant), where + ": use it on the patch.", here, at, current, done, total, plant.getSeedId());
			case CHECK_HEALTH:
				return task(t, "Check its health", where + ": check the " + spot.kindName().toLowerCase() + "'s health.", here, at, current, done, total);
			case HARVEST:
				return task(t, Planner.harvestText(spot, r.getProduce() == null ? "" : r.getProduce().getName().toLowerCase()), where, here, at,
					current, done, total, kind == PatchKind.BELLADONNA ? Supplies.GLOVES : Supplies.SECATEURS);
			case CHOP:
				if (Planner.isTree(spot) && spot.getGardener() >= 0)
				{
					return task(t, "Pay to clear the tree", where + ": ask the gardener to remove it for 200 coins.",
						Step.Target.npc(at, spot.getGardener()), at, current, done, total, ItemID.COINS);
				}
				return task(t, "Chop it down", where + ": chop it with your axe.", here, at, current, done, total,
					owned(Supplies.AXES, w.ability).stream().mapToInt(Integer::intValue).toArray());
			case CLEAR:
				return task(t, "Dig it up", where + ": clear it with your spade.", here, at, current, done, total, ItemID.SPADE);
			case CURE:
				return task(t, "Cure the disease", where + ": use a plant cure on it.", here, at, current, done, total, ItemID.PLANT_CURE);
			case PRUNE:
				return task(t, "Prune the disease", where + ": prune it with secateurs.", here, at, current, done, total, Supplies.SECATEURS);
			default:
				return task(t, r.getSummary(), where, here, at, current, done, total);
		}
	}

	static int[] carriedHouses(World w)
	{
		List<Integer> ids = new ArrayList<>();
		Birdhouse.Type[] all = Birdhouse.Type.values();
		for (int i = all.length - 1; i >= 0; i--)
		{
			if (all[i].getHunterLevel() <= w.ability.getHunter() && w.carrying(all[i].getItemId()) > 0)
			{
				ids.add(all[i].getItemId());
			}
		}
		return ids.stream().mapToInt(Integer::intValue).toArray();
	}

	private static Step task(Task t, String title, String detail, Step.Target target, Point at, int current, int done, int total, int... items)
	{
		List<Integer> list = new ArrayList<>();
		for (int i : items)
		{
			list.add(i);
		}
		return new Step(Step.Kind.TASK, title, detail, target, list, at, t, current, done, total);
	}

	/** Required lines of the pull list the player isn't carrying enough of. */
	/** What still has to come from the bank: stored tools are left out when the first stop has a leprechaun. */
	public static List<Need> missing(Route route, World w)
	{
		boolean leprechaunFirst = !route.getStops().isEmpty() && Leprechaun.PLACES.contains(route.getStops().get(0).getPlace());
		List<Need> out = new ArrayList<>();
		for (Need n : route.getPulls())
		{
			if (n.isOptional())
			{
				continue;
			}
			int have = w.carrying(n.getItems());
			if (leprechaunFirst && Leprechaun.holds(n))
			{
				have += w.ability.stored(n.getItems());
			}
			if (have < n.getQuantity())
			{
				out.add(n);
			}
		}
		return out;
	}

	/** Tools and compost the round needs that are with the leprechaun rather than in the pack. */
	static List<Need> fromLeprechaun(List<Need> pulls, World w)
	{
		List<Need> out = new ArrayList<>();
		for (Need n : pulls)
		{
			if (Leprechaun.holds(n) && w.carrying(n.getItems()) < n.getQuantity() && w.ability.stored(n.getItems()) > 0)
			{
				out.add(n);
			}
		}
		return out;
	}
}

package com.codex.rounds.core;

import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;

/**
 * The Kingdom of Miscellania. Approval (0 to 127) and the coffer live in varbits; away from the
 * kingdom both are estimated from the last values seen, the way RuneLite's Kingdom plugin does:
 * every day the coffer pays out a tenth of itself, capped at 50k (75k after Royal Trouble), and
 * approval falls by 2.5% (1% after Royal Trouble).
 */
public final class Kingdom
{
	public static final int MAX_APPROVAL = 127;
	public static final int MAX_COFFER = 7_500_000;
	public static final int[] REGIONS = {10044, 10300};

	private final int approval;
	private final int coffer;
	private final boolean royalTrouble;
	private final boolean estimated;

	public Kingdom(int approval, int coffer, boolean royalTrouble, boolean estimated)
	{
		this.approval = approval;
		this.coffer = coffer;
		this.royalTrouble = royalTrouble;
		this.estimated = estimated;
	}

	/** Today's kingdom, from a snapshot taken at {@code seenAt}. */
	public static Kingdom estimate(int approval, int coffer, long seenAt, long now, boolean royalTrouble)
	{
		int days = daysBetween(seenAt, now);
		int withdrawal = withdrawalCap(royalTrouble);
		int threshold = withdrawal * 10;
		int c = coffer;
		for (int i = 0; i < days && c > 0; i++)
		{
			c -= c > threshold ? withdrawal : c / 10;
		}
		float daily = royalTrouble ? 0.010f : 0.025f;
		int a = Math.max(0, approval - (int) (days * daily * MAX_APPROVAL));
		return new Kingdom(a, c, royalTrouble, days > 0);
	}

	public static int withdrawalCap(boolean royalTrouble)
	{
		return royalTrouble ? 75_000 : 50_000;
	}

	/** The coffer that keeps the full daily payout flowing: ten days of the cap. */
	public static int fullPayoutCoffer(boolean royalTrouble)
	{
		return withdrawalCap(royalTrouble) * 10;
	}

	static int daysBetween(long from, long to)
	{
		Instant a = Instant.ofEpochSecond(from).truncatedTo(ChronoUnit.DAYS);
		Instant b = Instant.ofEpochSecond(to).truncatedTo(ChronoUnit.DAYS);
		return (int) Math.max(0, Duration.between(a, b).toDays());
	}

	public int getApproval()
	{
		return approval;
	}

	public int approvalPercent()
	{
		return approval * 100 / MAX_APPROVAL;
	}

	public int getCoffer()
	{
		return coffer;
	}

	public boolean isRoyalTrouble()
	{
		return royalTrouble;
	}

	/** Whether the numbers are a guess carried forward from an earlier visit. */
	public boolean isEstimated()
	{
		return estimated;
	}

	/** Coins to deposit to reach the target, never past the coffer's cap. */
	public int topUp(int target)
	{
		int t = Math.min(MAX_COFFER, Math.max(0, target));
		return Math.max(0, t - coffer);
	}

	/** Whether a visit is due under the player's thresholds. */
	public boolean needsVisit(int approvalTargetPercent, int cofferTarget, int topUpSlack)
	{
		return approvalPercent() < approvalTargetPercent || topUp(cofferTarget) > topUpSlack;
	}

	/** Days until approval falls below a percentage, at the daily drop. */
	public int daysUntilApprovalBelow(int percent)
	{
		float daily = royalTrouble ? 0.010f : 0.025f;
		int perDay = Math.max(1, (int) (daily * MAX_APPROVAL));
		int floor = (percent * MAX_APPROVAL + 99) / 100;
		int above = approval - floor;
		return above < 0 ? 0 : above / perDay + 1;
	}
}

package com.codex.rounds.core;

import java.util.Arrays;

/**
 * One way of getting to a place: an item or spell that teleports, a fairy ring, or plain
 * directions when nothing better is known. Landing spots come from the Shortest Path plugin's
 * transport data (Skretzo, BSD 2-Clause).
 */
public final class Leg
{
	public enum Kind
	{
		ITEM,
		SPELL,
		FAIRY_RING,
		DIRECTIONS
	}

	/** Standard, Ancient, Lunar, Arceuus: the game's spellbook varbit values. */
	public static final int STANDARD = 0;
	public static final int ANCIENT = 1;
	public static final int LUNAR = 2;
	public static final int ARCEUUS = 3;

	private final Kind kind;
	private final String label;
	private final Point landing;
	private final int[] items;
	private final int magicLevel;
	private final int spellbook;
	private final int extraSeconds;
	private Unlock requires;

	private Leg(Kind kind, String label, Point landing, int[] items, int magicLevel, int spellbook, int extraSeconds)
	{
		this.kind = kind;
		this.label = label;
		this.landing = landing;
		this.items = items;
		this.magicLevel = magicLevel;
		this.spellbook = spellbook;
		this.extraSeconds = extraSeconds;
	}

	/** Teleport with any one of these items. */
	public static Leg item(String label, int x, int y, int... items)
	{
		return new Leg(Kind.ITEM, label, Point.of(x, y), items, 0, -1, 0);
	}

	public static Leg spell(String label, int x, int y, int level, int spellbook)
	{
		return new Leg(Kind.SPELL, label, Point.of(x, y), new int[0], level, spellbook, 0);
	}

	/** A fairy ring, reached from a ring in the house or by teleporting to one first. */
	public static Leg ring(String code, int x, int y)
	{
		return new Leg(Kind.FAIRY_RING, "Fairy ring " + code, Point.of(x, y), new int[0], 0, -1, 25);
	}

	/** Plain directions, always possible but slow. */
	public static Leg directions(String label, int x, int y, int seconds)
	{
		return new Leg(Kind.DIRECTIONS, label, Point.of(x, y), new int[0], 0, -1, seconds);
	}

	/** The same leg, open only once the account has this unlock. */
	public Leg needs(Unlock unlock)
	{
		Leg copy = new Leg(kind, label, landing, items, magicLevel, spellbook, extraSeconds);
		copy.requires = unlock;
		return copy;
	}

	public Unlock getRequires()
	{
		return requires;
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getLabel()
	{
		return label;
	}

	public Point getLanding()
	{
		return landing;
	}

	/** The items that can make this teleport, any one of them. */
	public int[] getItems()
	{
		return items.clone();
	}

	public int getMagicLevel()
	{
		return magicLevel;
	}

	public int getSpellbook()
	{
		return spellbook;
	}

	/** Rough seconds to use this leg before any walking: casting, rubbing, dialling a ring. */
	public int overheadSeconds()
	{
		switch (kind)
		{
			case ITEM:
				// Taking the item out, rubbing or operating it, the destination menu, the animation and the load.
				return 14;
			case SPELL:
				return 10;
			case FAIRY_RING:
				return 5 + extraSeconds;
			default:
				return extraSeconds;
		}
	}

	public boolean usesItem(int itemId)
	{
		return Arrays.stream(items).anyMatch(i -> i == itemId);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.codex.rounds.core;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;

/**
 * The tools and compost stored with the tool leprechaun. The game sends these varbits everywhere, so the store is
 * known without a visit. Large counts spill into an "extra" varbit worth 2 (tools) or 256 (compost) each.
 */
public final class Leprechaun
{
	/** Stops where a tool leprechaun stands by the patches, so stored tools can be taken out there. */
	public static final Set<Place> PLACES = EnumSet.of(Place.FARMING_GUILD, Place.FOSSIL_ISLAND, Place.UNDERWATER,
		Place.TAI_BWO_WANNAI, Place.PRIFDDINAS, Place.HOSIDIUS, Place.ETCETERIA, Place.BRIMHAVEN, Place.PORT_SARIM,
		Place.RIMMINGTON, Place.ARDOUGNE_MONASTERY, Place.CHAMPIONS_GUILD, Place.AL_KHARID, Place.DRAYNOR_MANOR,
		Place.CANIFIS, Place.KASTORI, Place.AUBURNVALE);

	public static final int[] NPCS = {NpcID.FARMING_TOOLS_LEPRECHAUN, NpcID.FOSSIL_LEPRECHAUN_UNDERWATER,
		NpcID.FARMING_TOOLS_LEPRECHAUN_VARLAMORE, NpcID.FARMING_TOOLS_LEPRECHAUN_DRAYNOR};

	private static final int NONE = -1;

	/** Item, base varbit, extra varbit, shift of the extra varbit. */
	private static final int[][] SLOTS = {
		{ItemID.RAKE, VarbitID.FARMING_TOOLS_RAKE, VarbitID.FARMING_TOOLS_EXTRARAKES, 1},
		{ItemID.DIBBER, VarbitID.FARMING_TOOLS_DIBBER, VarbitID.FARMING_TOOLS_EXTRADIBBERS, 1},
		{ItemID.SPADE, VarbitID.FARMING_TOOLS_SPADE, VarbitID.FARMING_TOOLS_EXTRASPADES, 1},
		{ItemID.SECATEURS, VarbitID.FARMING_TOOLS_SECATEURS, VarbitID.FARMING_TOOLS_EXTRASECATEURS, 1},
		{ItemID.BUCKET_COMPOST, VarbitID.FARMING_TOOLS_COMPOST, VarbitID.FARMING_TOOLS_EXTRACOMPOST, 8},
		{ItemID.BUCKET_SUPERCOMPOST, VarbitID.FARMING_TOOLS_SUPERCOMPOST, VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST, 8},
		{ItemID.BUCKET_ULTRACOMPOST, VarbitID.FARMING_TOOLS_ULTRACOMPOST, NONE, 0},
		{ItemID.PLANT_CURE, VarbitID.FARMING_TOOLS_PLANTCURE, NONE, 0},
	};

	private Leprechaun()
	{
	}

	public static Map<Integer, Integer> read(Vars vars)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (int[] s : SLOTS)
		{
			int n = vars.varbit(s[1]) + (s[2] == NONE ? 0 : vars.varbit(s[2]) << s[3]);
			if (n > 0)
			{
				out.put(s[0], n);
			}
		}
		// The secateurs slot holds magic secateurs when this flag is set.
		Integer secateurs = out.get(ItemID.SECATEURS);
		if (secateurs != null && vars.varbit(VarbitID.FARMING_TOOLS_FAIRYSECATEURS) > 0)
		{
			out.remove(ItemID.SECATEURS);
			out.put(ItemID.FAIRY_ENCHANTED_SECATEURS, secateurs);
		}
		return out;
	}

	/** Whether this need can come out of the leprechaun's store: farming tools, compost and cures. */
	public static boolean holds(Need n)
	{
		for (int id : n.getItems())
		{
			if (id == ItemID.FAIRY_ENCHANTED_SECATEURS)
			{
				return true;
			}
			for (int[] s : SLOTS)
			{
				if (s[0] == id)
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.codex.rounds.core;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything Rounds remembers for one account, saved as JSON in the RuneLite profile. Fields
 * are plain so Gson can read older saves; anything missing reads as empty.
 */
public final class Memory
{
	/** Spot key to "value:unixtime", the same form as RuneLite's Time Tracking. */
	public Map<String, String> seen = new HashMap<>();
	/** Items counted across bank, pack and worn gear. */
	public Map<Integer, Integer> bank = new HashMap<>();
	public Map<Integer, Integer> carried = new HashMap<>();
	public long bankTime;
	/** Teleport unlocks, by name; null until quests were first read. */
	public Set<String> unlocks;
	/** The running farming contract's type varbit, 0 when none or when done. */
	public int contractType;
	/** Measured teleport legs: key to average seconds and how many laps it is drawn from. */
	public Map<String, Pace> paces = new HashMap<>();
	/** Tools and compost with the tool leprechaun, as last read. */
	public Map<Integer, Integer> stored = new HashMap<>();

	public Integer kingdomApproval;
	public Integer kingdomCoffer;
	public long kingdomTime;
	public boolean kingdomQuest;
	public boolean royalTrouble;

	/** Daily name to what was last seen of it. */
	public Map<String, DailySnap> dailies = new HashMap<>();

	public int farming = 1;
	public int hunter = 1;
	public int crafting = 1;
	public int magic = 1;
	public int spellbook;
	public boolean fairyRings;

	/** Finished rounds, newest last, kept short. */
	public List<RoundRecord> rounds = new ArrayList<>();

	public static final class DailySnap
	{
		public boolean unlocked;
		public boolean claimable;
		public long seenAt;
		public String reward;
		public int needQuantity;
	}

	public static final class RoundRecord
	{
		public long finishedAt;
		public int seconds;
		public int chores;
		public int stops;

		public RoundRecord()
		{
		}

		public RoundRecord(long finishedAt, int seconds, int chores, int stops)
		{
			this.finishedAt = finishedAt;
			this.seconds = seconds;
			this.chores = chores;
			this.stops = stops;
		}
	}

	public Seen seen(Spot spot)
	{
		return seen == null ? null : Seen.parse(seen.get(spot.key()));
	}

	public void put(Spot spot, Seen s)
	{
		if (seen == null)
		{
			seen = new HashMap<>();
		}
		seen.put(spot.key(), s.toString());
	}

	public Map<Spot, Seen> seenMap()
	{
		Map<Spot, Seen> out = new java.util.EnumMap<>(Spot.class);
		for (Spot s : Spot.values())
		{
			Seen v = seen(s);
			if (v != null)
			{
				out.put(s, v);
			}
		}
		return out;
	}

	/** Takes an outside reading (from Time Tracking) when it is newer than ours. */
	public boolean adopt(Spot spot, Seen outside)
	{
		if (outside == null)
		{
			return false;
		}
		Seen mine = seen(spot);
		if (mine == null || (outside.getTime() > mine.getTime() && outside.getValue() != mine.getValue()))
		{
			put(spot, outside);
			return true;
		}
		return false;
	}

	/** The kingdom today, estimated from the last snapshot, or null when unknown. */
	public Kingdom kingdom(long now)
	{
		if (!kingdomQuest || kingdomApproval == null || kingdomCoffer == null || kingdomTime <= 0)
		{
			return null;
		}
		return Kingdom.estimate(kingdomApproval, kingdomCoffer, kingdomTime, now, royalTrouble);
	}

	/** Dailies as last seen, reset at midnight UTC since. */
	public List<DailyState> dailyStates(long now)
	{
		List<DailyState> out = new ArrayList<>();
		if (dailies == null)
		{
			return out;
		}
		for (Daily d : Daily.values())
		{
			DailySnap snap = dailies.get(d.name());
			if (snap == null)
			{
				continue;
			}
			Need need = null;
			if (snap.needQuantity > 0)
			{
				need = d.need(new Vars()
				{
					@Override
					public int varbit(int id)
					{
						return 0;
					}

					@Override
					public int varp(int id)
					{
						return 0;
					}
				});
				if (need != null)
				{
					need = new Need(need.getKind(), need.getLabel(), snap.needQuantity, need.getWhy(), need.isOptional(), need.getItems());
				}
			}
			DailyState st = new DailyState(d, snap.unlocked, snap.claimable, snap.reward == null ? "" : snap.reward, need);
			boolean reset = d.resetsDaily() && now / 86400 > snap.seenAt / 86400;
			out.add(reset ? st.afterReset() : st);
		}
		return out;
	}

	public void snapDaily(DailyState st, long now)
	{
		if (dailies == null)
		{
			dailies = new HashMap<>();
		}
		DailySnap snap = new DailySnap();
		snap.unlocked = st.isUnlocked();
		snap.claimable = st.isClaimable();
		snap.seenAt = now;
		snap.reward = st.getReward();
		snap.needQuantity = st.getNeed() == null ? 0 : st.getNeed().getQuantity();
		dailies.put(st.getDaily().name(), snap);
	}

	public Ability ability()
	{
		Ability.Builder b = Ability.builder()
			.levels(farming, hunter, crafting, magic)
			.spellbook(spellbook)
			.fairyRings(fairyRings)
			.bankKnown(bankTime > 0)
			.items(bank)
			.items(carried)
			.stored(stored)
			.paces(paceMap())
			.unlocks(unlockSet());
		return b.build();
	}

	/** A leg's running average, weighted toward recent laps so it follows the player getting quicker. */
	public static final class Pace
	{
		public double seconds;
		public int laps;
	}

	/** Laps it takes before a measured leg replaces the estimate. */
	static final int PACE_LAPS = 2;
	private static final int PACE_WINDOW = 5;

	public void lap(String key, int seconds)
	{
		if (paces == null)
		{
			paces = new HashMap<>();
		}
		Pace p = paces.computeIfAbsent(key, k -> new Pace());
		int n = Math.min(p.laps, PACE_WINDOW - 1);
		p.seconds = (p.seconds * n + seconds) / (n + 1);
		p.laps++;
	}

	Set<Unlock> unlockSet()
	{
		if (unlocks == null)
		{
			return null;
		}
		Set<Unlock> out = EnumSet.noneOf(Unlock.class);
		for (String u : unlocks)
		{
			try
			{
				out.add(Unlock.valueOf(u));
			}
			catch (IllegalArgumentException e)
			{
				// A name from a later version: ignore it.
			}
		}
		return out;
	}

	Map<String, Integer> paceMap()
	{
		Map<String, Integer> out = new HashMap<>();
		if (paces != null)
		{
			paces.forEach((k, p) ->
			{
				if (p != null && p.laps >= PACE_LAPS)
				{
					out.put(k, (int) Math.round(p.seconds));
				}
			});
		}
		return out;
	}

	public void record(RoundRecord r)
	{
		if (rounds == null)
		{
			rounds = new ArrayList<>();
		}
		rounds.add(r);
		while (rounds.size() > 30)
		{
			rounds.remove(0);
		}
	}

	/** The fastest finished round, or null. */
	public RoundRecord best()
	{
		RoundRecord best = null;
		if (rounds != null)
		{
			for (RoundRecord r : rounds)
			{
				if (best == null || r.seconds < best.seconds)
				{
					best = r;
				}
			}
		}
		return best;
	}
}

package com.codex.rounds.core;

import java.util.Arrays;

/** One line of the pull list: any of some items, how many, and why. */
public final class Need
{
	public enum Kind
	{
		TELEPORT("Teleports"),
		TOOL("Tools"),
		PLANT("Seeds and saplings"),
		CARE("Compost and cures"),
		PAYMENT("Gardener payments"),
		BIRDHOUSE("Bird houses"),
		DAILY("Dailies"),
		COINS("Coins");

		private final String label;

		Kind(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	private final Kind kind;
	private final String label;
	private final int[] items;
	private final int quantity;
	private final String why;
	private final boolean optional;

	public Need(Kind kind, String label, int quantity, String why, boolean optional, int... items)
	{
		this.kind = kind;
		this.label = label;
		this.items = items;
		this.quantity = quantity;
		this.why = why;
		this.optional = optional;
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getLabel()
	{
		return label;
	}

	/** The first item is the one to show; any of them will do. */
	public int[] getItems()
	{
		return items.clone();
	}

	public int getItemId()
	{
		return items.length == 0 ? -1 : items[0];
	}

	public int getQuantity()
	{
		return quantity;
	}

	public String getWhy()
	{
		return why;
	}

	public boolean isOptional()
	{
		return optional;
	}

	public boolean accepts(int itemId)
	{
		return Arrays.stream(items).anyMatch(i -> i == itemId);
	}

	/** The same need with a larger quantity, for merging lines. */
	Need plus(int more, String moreWhy)
	{
		String w = why == null || why.isEmpty() ? moreWhy : moreWhy == null || moreWhy.isEmpty() || why.contains(moreWhy) ? why : why + ", " + moreWhy;
		return new Need(kind, label, quantity + more, w, optional, items);
	}

	@Override
	public String toString()
	{
		return quantity + " x " + label;
	}
}

