	private final String label;
	private final String detail;
	private final Point anchor;
	private final int radius;
	private final List<Leg> legs;
	private final Place via;
	private final String localStep;
	private final Point localPoint;
	private final int localObject;

	Place(String label, String detail, Point anchor, int radius, Leg... legs)
	{
		this.label = label;
		this.detail = detail;
		this.anchor = anchor;
		this.radius = radius;
		this.legs = Collections.unmodifiableList(Arrays.asList(legs));
		this.via = null;
		this.localStep = null;
		this.localPoint = null;
		this.localObject = -1;
	}

	Place(String label, String detail, Point anchor, int radius, Place via, String localStep, Point localPoint, int localObject)
	{
		this.label = label;
		this.detail = detail;
		this.anchor = anchor;
		this.radius = radius;
		this.legs = Collections.emptyList();
		this.via = via;
		this.localStep = localStep;
		this.localPoint = localPoint;
		this.localObject = localObject;
	}

	public String getLabel()
	{
		return label;
	}

	public String getDetail()
	{
		return detail;
	}

	public Point getAnchor()
	{
		return anchor;
	}

	/** The ways to get here, best first. Empty for a place reached through {@link #getVia()}. */
	public List<Leg> getLegs()
	{
		return legs;
	}

	/** The place this one is reached through, or null. */
	public Place getVia()
	{
		return via;
	}

	/** The last step from {@link #getVia()} to here. */
	public String getLocalStep()
	{
		return localStep;
	}

	public Point getLocalPoint()
	{
		return localPoint;
	}

	/** The object to use for the last step from the place this one is reached through, or -1. */
	public int getLocalObject()
	{
		return localObject;
	}

	/** Whether someone standing here has arrived. */
	public boolean contains(Point p)
	{
		return p != null && p.sameMap(anchor) && p.distance(anchor) <= radius;
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.Action;
import com.codex.rounds.core.farming.PatchKind;
import com.codex.rounds.core.farming.Produce;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Turns the board into a round: which places to visit, in what order, what to do at each and
 * what to bring. The order starts greedy (nearest next) and is then improved by moving single
 * stops and reversing runs of stops until nothing gets faster.
 */
public final class Planner
{
	private Planner()
	{
	}

	public static Route plan(Board board, List<DailyState> dailies, Settings settings, Ability ability, Point start, long now)
	{
		long lookahead = settings.getLookaheadMinutes() * 60L;
		Map<Place, List<Task>> byPlace = new LinkedHashMap<>();
		Map<Daily, DailyState> dailyStates = new EnumMap<>(Daily.class);
		for (DailyState d : dailies)
		{
			dailyStates.put(d.getDaily(), d);
		}

		for (Board.Entry e : board.getEntries())
		{
			Task t = null;
			switch (e.getType())
			{
				case SPOT:
					Reading r = e.getReading();
					if (settings.wants(e.getSpot()) && r.dueWithin(now, lookahead) && (r.getStatus() != Status.UNSEEN || settings.isIncludeUnseen()))
					{
						t = spotTask(e.getSpot(), r, settings, ability);
					}
					break;
				case DAILY:
					if (e.getStatus() == Status.READY && settings.wants(e.getDaily()))
					{
						DailyState ds = dailyStates.get(e.getDaily());
						t = new Task(Board.Type.DAILY, null, e.getDaily(), null, null, false, false,
							e.getDaily().getAction(), ds == null ? e.getDetail() : ds.getReward(), 20);
					}
					break;
				case KINGDOM:
					if (e.getStatus() == Status.READY && settings.isKingdom())
					{
						t = kingdomTask(board.getKingdom(), settings);
					}
					break;
			}
			if (t != null)
			{
				byPlace.computeIfAbsent(e.getPlace(), p -> new ArrayList<>()).add(t);
			}
		}

		if (byPlace.isEmpty())
		{
			return new Route(new ArrayList<>(), new ArrayList<>(), now);
		}

		List<Place> order = order(new ArrayList<>(byPlace.keySet()), start, ability);
		List<Stop> stops = new ArrayList<>();
		Point at = start;
		for (Place p : order)
		{
			Travel.Way way = Travel.best(at, p, ability);
			stops.add(new Stop(p, way, byPlace.get(p)));
			at = exit(p);
		}
		return new Route(stops, Supplies.forStops(stops, dailyStates, board.getKingdom(), settings, ability), now);
	}

	/** Where you stand after finishing a place: the seabed and Hespori's cave come back up to the surface. */
	static Point exit(Place p)
	{
		return p.getVia() != null ? p.getLocalPoint() : p.getAnchor();
	}

	static int cost(Point from, Place to, Ability ability)
	{
		return Travel.best(from, to, ability).getSeconds();
	}

	static int total(List<Place> order, Point start, Ability ability, Map<Long, Integer> memo)
	{
		int sum = 0;
		Point at = start;
		Place prev = null;
		for (Place p : order)
		{
			long key = ((long) (prev == null ? 999 : prev.ordinal()) << 16) | p.ordinal();
			Integer c = memo.get(key);
			if (c == null)
			{
				c = cost(at, p, ability);
				memo.put(key, c);
			}
			sum += c;
			at = exit(p);
			prev = p;
		}
		return sum;
	}

	static List<Place> order(List<Place> places, Point start, Ability ability)
	{
		// Greedy: always go to the cheapest next place.
		List<Place> left = new ArrayList<>(places);
		List<Place> order = new ArrayList<>();
		Point at = start;
		while (!left.isEmpty())
		{
			Place best = null;
			int bestCost = Integer.MAX_VALUE;
			for (Place p : left)
			{
				int c = cost(at, p, ability);
				if (c < bestCost)
				{
					bestCost = c;
					best = p;
				}
			}
			order.add(best);
			left.remove(best);
			at = exit(best);
		}

		// Improve: relocate single stops and reverse runs until no move helps.
		Map<Long, Integer> memo = new java.util.HashMap<>();
		int current = total(order, start, ability, memo);
		boolean improved = true;
		int guard = 0;
		while (improved && guard++ < 50)
		{
			improved = false;
			for (int i = 0; i < order.size(); i++)
			{
				for (int j = 0; j < order.size(); j++)
				{
					if (i == j)
					{
						continue;
					}
					List<Place> trial = new ArrayList<>(order);
					Place moved = trial.remove(i);
					trial.add(j, moved);
					int t = total(trial, start, ability, memo);
					if (t < current)
					{
						order = trial;
						current = t;
						improved = true;
					}
				}
			}
			for (int i = 0; i < order.size() - 1; i++)
			{
				for (int j = i + 1; j < order.size(); j++)
				{
					List<Place> trial = new ArrayList<>(order);
					java.util.Collections.reverse(trial.subList(i, j + 1));
					int t = total(trial, start, ability, memo);
					if (t < current)
					{
						order = trial;
						current = t;
						improved = true;
					}
				}
			}
		}
		return order;
	}

	static Task kingdomTask(Kingdom k, Settings s)
	{
		List<String> parts = new ArrayList<>();
		int topUp = k.topUp(s.getCofferTarget());
		if (topUp > s.getTopUpSlack())
		{
			parts.add("deposit " + Format.coins(topUp));
		}
		if (k.approvalPercent() < s.getApprovalTarget())
		{
			parts.add("raise approval from " + k.approvalPercent() + "% to " + s.getApprovalTarget() + "%");
		}
		String detail = parts.isEmpty() ? "Check in with Advisor Ghrim" : capitalise(String.join(" and ", parts));
		int seconds = 30 + (k.approvalPercent() < s.getApprovalTarget() ? (s.getApprovalTarget() - k.approvalPercent()) * 6 : 0);
		return new Task(Board.Type.KINGDOM, null, null, null, null, false, false, "Look after Miscellania", detail, seconds);
	}

	static String capitalise(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	static Task spotTask(Spot spot, Reading r, Settings settings, Ability ability)
	{
		if (spot.isBirdhouse())
		{
			Birdhouse.State st = r.getHouse();
			String detail;
			int secs;
			if (st == null)
			{
				detail = "Look at the space; build and seed it if empty";
				secs = 12;
			}
			else
			{
				switch (st)
				{
					case EMPTY:
						detail = "Build a bird house and add seeds";
						secs = 10;
						break;
					case BUILT:
						detail = "Add ten seeds";
						secs = 5;
						break;
					default:
						detail = r.getStatus() == Status.READY ? "Collect, rebuild and add seeds" : "Nearly full: collect, rebuild and reseed";
						secs = 15;
						break;
				}
			}
			return new Task(Board.Type.SPOT, spot, null, r, null, false, false, spot.getTitle(), detail, secs);
		}

		Produce plant = leavesEmpty(spot, r, settings) ? choosePlant(spot.getKind(), settings, ability) : null;
		Produce contract = settings.getContract();
		if (plant != null && contract != null && spot.getPlace() == Place.FARMING_GUILD && contract.getKind() == spot.getKind()
			&& contract.getLevel() <= ability.getFarming())
		{
			// Guildmaster Jane's contract wins over the usual pick for the guild's own patch.
			plant = contract;
		}
		boolean compost = plant != null && settings.getCompost() != Settings.Compost.NONE && spot.getKind() != PatchKind.HESPORI
			&& spot.getKind() != PatchKind.CRYSTAL_TREE;
		boolean protect = plant != null && settings.isProtect() && plant.isProtectable() && spot.getGardener() >= 0;
		String detail = spotDetail(spot, r, plant);
		int secs = workSeconds(spot, r) + (plant != null ? 10 : 0) + (compost ? 3 : 0) + (protect ? 8 : 0);
		return new Task(Board.Type.SPOT, spot, null, r, plant, compost, protect, spot.getTitle(), detail, secs);
	}

	static boolean isTree(Spot spot)
	{
		PatchKind k = spot.getKind();
		return k == PatchKind.HARDWOOD_TREE || k == PatchKind.REDWOOD || k == PatchKind.SPIRIT_TREE;
	}

	static boolean regrows(PatchKind k)
	{
		return k == PatchKind.BUSH || k == PatchKind.CACTUS;
	}

	/** Whether this visit leaves the patch empty and ready to replant. */
	static boolean leavesEmpty(Spot spot, Reading r, Settings settings)
	{
		PatchKind k = spot.getKind();
		if (r.getStatus() == Status.UNSEEN)
		{
			return true;
		}
		if (r.getAction() == null)
		{
			return false;
		}
		switch (r.getAction())
		{
			case PLANT:
			case RAKE:
			case CLEAR:
			case CHOP:
				return true;
			case CHECK_HEALTH:
				if (k == PatchKind.SPIRIT_TREE)
				{
					return !settings.isKeepSpiritTrees();
				}
				return !regrows(k);
			case HARVEST:
				return !regrows(k);
			default:
				return false;
		}
	}

	/** The crop to plant: the player's pick if they can plant it, else the best they own, else the best they could. */
	public static Produce choosePlant(PatchKind kind, Settings settings, Ability ability)
	{
		Produce chosen = settings.getCrop(kind);
		if (chosen != null && chosen.getLevel() <= ability.getFarming())
		{
			return chosen;
		}
		Produce bestOwned = null;
		Produce bestAny = null;
		for (Produce p : Produce.forKind(kind))
		{
			if (p.getLevel() > ability.getFarming())
			{
				continue;
			}
			bestAny = p;
			if (ability.owns(p.getSeedId()))
			{
				bestOwned = p;
			}
		}
		if (bestOwned != null)
		{
			return bestOwned;
		}
		if (kind == PatchKind.ANIMA || kind == PatchKind.HESPORI)
		{
			// Rare seeds: only plan one the account has, or might have when the bank is unknown.
			return ability.isBankKnown() ? null : bestAny;
		}
		return bestAny;
	}

	static int workSeconds(Spot spot, Reading r)
	{
		if (r.getStatus() == Status.UNSEEN || r.getAction() == null)
		{
			return 15;
		}
		PatchKind k = spot.getKind();
		switch (r.getAction())
		{
			case HARVEST:
				if (k == PatchKind.HESPORI)
				{
					return 90;
				}
				return k == PatchKind.SEAWEED || k == PatchKind.CALQUAT ? 25 : 12;
			case CHECK_HEALTH:
				return isTree(spot) ? 15 : 20;
			case CHOP:
			case CLEAR:
				return 10;
			case RAKE:
				return 15;
			case CURE:
			case PRUNE:
				return 8;
			default:
				return 5;
		}
	}

	static String spotDetail(Spot spot, Reading r, Produce plant)
	{
		String then = plant == null ? "" : ", then plant " + seedName(plant);
		if (r.getStatus() == Status.UNSEEN)
		{
			return "Not seen yet: look at it" + (plant == null ? "" : " and plant " + seedName(plant) + " if it is empty");
		}
		Produce p = r.getProduce();
		String crop = p == null ? "" : p.getName().toLowerCase();
		switch (r.getAction())
		{
			case PLANT:
				return plant == null ? "Empty" : "Plant " + seedName(plant);
			case RAKE:
				return "Rake the weeds" + then;
			case CHECK_HEALTH:
				if (spot.getKind() == PatchKind.SPIRIT_TREE && plant == null)
				{
					return "Check the spirit tree's health and keep it";
				}
				return "Check the " + crop + "'s health" + clearText(spot, r) + then;
			case HARVEST:
				return harvestText(spot, crop) + then;
			case CHOP:
			case CLEAR:
				return capitalise(clearText(spot, r).replaceFirst("^, ", "")) + then;
			case CURE:
				return "Cure the disease with a plant cure";
			case PRUNE:
				return "Prune the disease with secateurs";
			default:
				return r.getSummary();
		}
	}

	static String clearText(Spot spot, Reading r)
	{
		if (r.getAction() == Action.CLEAR && r.getStatus() == Status.READY)
		{
			return ", dig it up";
		}
		if (isTree(spot) && spot.getGardener() >= 0)
		{
			return ", pay the gardener 200 coins to clear it";
		}
		if (spot.getKind() == PatchKind.CRYSTAL_TREE || spot.getKind() == PatchKind.CELASTRUS)
		{
			return ", chop it down and dig up the stump";
		}
		return ", dig it up";
	}

	static String harvestText(Spot spot, String crop)
	{
		switch (spot.getKind())
		{
			case HESPORI:
				return "Defeat Hespori and pick its seeds";
			case SEAWEED:
				return "Pick the giant seaweed";
			case MUSHROOM:
				return "Pick the bittercaps";
			case BELLADONNA:
				return "Pick the nightshade (wear gloves)";
			case CALQUAT:
				return "Pick the calquat fruit and dig up the tree";
			case CELASTRUS:
				return "Harvest the bark, then clear the tree";
			case BUSH:
				return "Pick the berries";
			case CACTUS:
				return "cactus".equals(crop) ? "Pick the cactus spines" : "Pick the potato cacti";
			default:
				return "Harvest the " + crop;
		}
	}

	/** Whether a crop goes in as a sapling (planted with a spade) rather than a seed (with a dibber). */
	public static boolean isSapling(Produce p)
	{
		switch (p.getKind())
		{
			case HARDWOOD_TREE:
			case CALQUAT:
			case SPIRIT_TREE:
			case CELASTRUS:
			case REDWOOD:
			case CRYSTAL_TREE:
				return true;
			default:
				return false;
		}
	}

	/** What goes in the ground, with an article: "a teak sapling", "a seaweed spore". */
	public static String seedName(Produce p)
	{
		switch (p.getKind())
		{
			case SEAWEED:
				return "a seaweed spore";
			case MUSHROOM:
				return "a mushroom spore";
			case HESPORI:
				return "a Hespori seed";
			case BUSH:
				return article(p.getName()) + " bush seed";
			default:
				return article(p.getName()) + (isSapling(p) ? " sapling" : " seed");
		}
	}

	static String article(String name)
	{
		String n = name.toLowerCase();
		boolean vowel = "aeiou".indexOf(n.charAt(0)) >= 0;
		return (vowel ? "an " : "a ") + n;
	}
}

package com.codex.rounds.core;

/** A tile in the world, kept apart from the client's own class so the planning code runs anywhere. */
public final class Point
{
	private final int x;
	private final int y;
	private final int plane;

	public Point(int x, int y, int plane)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	public static Point of(int x, int y)
	{
		return new Point(x, y, 0);
	}

	public static Point of(int x, int y, int plane)
	{
		return new Point(x, y, plane);
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	public int getPlane()
	{
		return plane;
	}

	public int getRegionId()
	{
		return ((x >> 6) << 8) | (y >> 6);
	}

	/** Tiles between two points the way the game counts them, ignoring the plane. */
	public int distance(Point o)
	{
		return Math.max(Math.abs(x - o.x), Math.abs(y - o.y));
	}

	/** Underground and instanced areas sit far from the surface map; a walk between them is not a walk. */
	public boolean sameMap(Point o)
	{
		return (y >= 6400) == (o.y >= 6400);
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Point))
		{
			return false;
		}
		Point p = (Point) o;
		return x == p.x && y == p.y && plane == p.plane;
	}

	@Override
	public int hashCode()
	{
		return (x * 31 + y) * 4 + plane;
	}

	@Override
	public String toString()
	{
		return x + "," + y + "," + plane;
	}
}

package com.codex.rounds.core;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** What has happened during the current round that game variables don't show. */
public final class Progress
{
	private final Set<String> skipped = new HashSet<>();
	private final Map<Spot, Long> planted = new EnumMap<>(Spot.class);
	private final Map<Spot, Long> composted = new EnumMap<>(Spot.class);
	private final Map<Spot, Long> paid = new EnumMap<>(Spot.class);
	private boolean suppliesDone;
	private boolean leprechaunDone;
	private int bankedChores;
	private int bankedStops;
	private final Set<Spot> sawReady = EnumSet.noneOf(Spot.class);
	private long startedAt;

	public static String key(Task t)
	{
		switch (t.getType())
		{
			case SPOT:
				return "spot:" + t.getSpot().name();
			case DAILY:
				return "daily:" + t.getDaily().name();
			default:
				return "kingdom";
		}
	}

	public void skip(Task t)
	{
		skipped.add(key(t));
	}

	public boolean isSkipped(Task t)
	{
		return skipped.contains(key(t));
	}

	public void planted(Spot s, long when)
	{
		planted.put(s, when);
		composted.remove(s);
		paid.remove(s);
	}

	public boolean wasPlanted(Spot s)
	{
		return planted.containsKey(s);
	}

	public void composted(Spot s, long when)
	{
		composted.put(s, when);
	}

	public boolean isComposted(Spot s)
	{
		return composted.containsKey(s);
	}

	public void paid(Spot s, long when)
	{
		paid.put(s, when);
	}

	public boolean isPaid(Spot s)
	{
		return paid.containsKey(s);
	}

	public boolean isSuppliesDone()
	{
		return suppliesDone;
	}

	public void suppliesDone()
	{
		this.suppliesDone = true;
	}

	/** Chores and stops finished before a mid-round replan, which drops them from the new route. */
	public void bank(int chores, int stops)
	{
		bankedChores += chores;
		bankedStops += stops;
	}

	public int getBankedChores()
	{
		return bankedChores;
	}

	public int getBankedStops()
	{
		return bankedStops;
	}

	/** A fresh reading during the round showed the spot ready, so growing again afterwards means it was harvested. */
	public void sawReady(Spot spot)
	{
		sawReady.add(spot);
	}

	public boolean wasSeenReady(Spot spot)
	{
		return sawReady.contains(spot);
	}

	public boolean isLeprechaunDone()
	{
		return leprechaunDone;
	}

	public void leprechaunDone()
	{
		this.leprechaunDone = true;
	}

	public long getStartedAt()
	{
		return startedAt;
	}

	public void start(long now)
	{
		skipped.clear();
		planted.clear();
		composted.clear();
		paid.clear();
		suppliesDone = false;
		leprechaunDone = false;
		bankedChores = 0;
		bankedStops = 0;
		sawReady.clear();
		startedAt = now;
	}

	public boolean isStarted()
	{
		return startedAt > 0;
	}

	public void stop()
	{
		startedAt = 0;
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.Action;
import com.codex.rounds.core.farming.PatchState;
import com.codex.rounds.core.farming.Produce;

/** What a spot is doing now, predicted from the last time it was seen. */
public final class Reading
{
	private final Spot spot;
	private final Seen seen;
	private final Status status;
	private final PatchState patch;
	private final Birdhouse.State house;
	private final Action action;
	private final long readyAt;
	private final String summary;

	private Reading(Spot spot, Seen seen, Status status, PatchState patch, Birdhouse.State house, Action action, long readyAt, String summary)
	{
		this.spot = spot;
		this.seen = seen;
		this.status = status;
		this.patch = patch;
		this.house = house;
		this.action = action;
		this.readyAt = readyAt;
		this.summary = summary;
	}

	static Reading unseen(Spot spot)
	{
		return new Reading(spot, null, Status.UNSEEN, null, null, null, 0, "Not seen yet");
	}

	static Reading birdhouse(Spot spot, Seen seen, Status status, Birdhouse.State house, long readyAt, String summary)
	{
		return new Reading(spot, seen, status, null, house, null, readyAt, summary);
	}

	static Reading patch(Spot spot, Seen seen, Status status, PatchState patch, Action action, long readyAt, String summary)
	{
		return new Reading(spot, seen, status, patch, null, action, readyAt, summary);
	}

	/** The same reading under another status, such as switched off or locked. */
	public Reading as(Status s, String why)
	{
		return new Reading(spot, seen, s, patch, house, action, readyAt, why);
	}

	public Spot getSpot()
	{
		return spot;
	}

	public Seen getSeen()
	{
		return seen;
	}

	public Status getStatus()
	{
		return status;
	}

	/** The patch as last seen, or null for bird houses and unseen patches. */
	public PatchState getPatch()
	{
		return patch;
	}

	public Birdhouse.State getHouse()
	{
		return house;
	}

	/** The next thing to do there, for patches. */
	public Action getAction()
	{
		return action;
	}

	/** Unix second it is (or was) ready, or 0 when not known. */
	public long getReadyAt()
	{
		return readyAt;
	}

	public String getSummary()
	{
		return summary;
	}

	/** What is growing, or null. */
	public Produce getProduce()
	{
		return patch == null || patch.isEmpty() ? null : patch.getProduce();
	}

	public boolean isEmpty()
	{
		return patch != null && patch.isEmpty();
	}

	/** Seconds until ready, or 0 when ready or unknown. */
	public long secondsLeft(long now)
	{
		return status == Status.GROWING && readyAt > now ? readyAt - now : 0;
	}

	/** Whether a round should stop for it within the lookahead. */
	public boolean dueWithin(long now, long lookahead)
	{
		return status == Status.READY || status == Status.UNSEEN
			|| (status == Status.GROWING && readyAt > 0 && readyAt <= now + lookahead);
	}
}

package com.codex.rounds.core;

import java.util.Collections;
import java.util.List;

/** A planned round: stops in order and the pull list. */
public final class Route
{
	public static final Route EMPTY = new Route(Collections.emptyList(), Collections.emptyList(), 0);

	private final List<Stop> stops;
	private final List<Need> pulls;
	private final long builtAt;

	Route(List<Stop> stops, List<Need> pulls, long builtAt)
	{
		this.stops = Collections.unmodifiableList(stops);
		this.pulls = Collections.unmodifiableList(pulls);
		this.builtAt = builtAt;
	}

	public List<Stop> getStops()
	{
		return stops;
	}

	public List<Need> getPulls()
	{
		return pulls;
	}

	public long getBuiltAt()
	{
		return builtAt;
	}

	public boolean isEmpty()
	{
		return stops.isEmpty();
	}

	public int getSeconds()
	{
		return stops.stream().mapToInt(Stop::getSeconds).sum();
	}

	public int taskCount()
	{
		return stops.stream().mapToInt(s -> s.getTasks().size()).sum();
	}
}

package com.codex.rounds.core;

import java.util.Objects;

/** A variable's value and the unix second it was first seen holding it. */
public final class Seen
{
	private final int value;
	private final long time;

	public Seen(int value, long time)
	{
		this.value = value;
		this.time = time;
	}

	public int getValue()
	{
		return value;
	}

	public long getTime()
	{
		return time;
	}

	/** Reads RuneLite's Time Tracking form, "value:unixtime". */
	public static Seen parse(String stored)
	{
		if (stored == null)
		{
			return null;
		}
		String[] parts = stored.split(":");
		if (parts.length != 2)
		{
			return null;
		}
		try
		{
			long time = Long.parseLong(parts[1]);
			return time > 0 ? new Seen(Integer.parseInt(parts[0]), time) : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Seen))
		{
			return false;
		}
		Seen s = (Seen) o;
		return value == s.value && time == s.time;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(value, time);
	}

	@Override
	public String toString()
	{
		return value + ":" + time;
	}
}

package com.codex.rounds.core;

import com.codex.rounds.core.farming.PatchKind;
import com.codex.rounds.core.farming.Produce;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** The player's choices for a round, gathered from the plugin's config. */
public final class Settings
{
	public enum Compost
	{
		ULTRACOMPOST("Ultracompost"),
		SUPERCOMPOST("Supercompost"),
		NONE("None");

		private final String label;

		Compost(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final Set<Spot.Group> groups = EnumSet.allOf(Spot.Group.class);
	private final Set<Spot> off = EnumSet.noneOf(Spot.class);
	private final Set<Daily> dailies = EnumSet.complementOf(EnumSet.of(Daily.LUNDAIL));
	private final Map<PatchKind, Produce> crops = new EnumMap<>(PatchKind.class);
	private boolean kingdom = true;
	private int approvalTarget = 100;
	private int cofferTarget = 750_000;
	private int topUpSlack = 100_000;
	private Compost compost = Compost.ULTRACOMPOST;
	private boolean protect = true;
	private boolean keepSpiritTrees = true;
	private boolean includeUnseen = true;
	private int lookaheadMinutes = 10;
	private Produce contract;

	public static Settings defaults()
	{
		return new Settings();
	}

	public boolean wants(Spot spot)
	{
		return groups.contains(spot.getGroup()) && !off.contains(spot);
	}

	public boolean wants(Daily daily)
	{
		return dailies.contains(daily);
	}

	/** The groups a quick loop covers: the Fossil Island chores that come round every hour. */
	public static final Set<Spot.Group> QUICK = EnumSet.of(Spot.Group.BIRDHOUSES, Spot.Group.SEAWEED);

	/** A copy for a quick loop: only bird houses and seaweed, no dailies or kingdom, the rest as set. */
	public Settings quickLoop()
	{
		Settings q = new Settings();
		q.groups.retainAll(QUICK);
		q.groups.retainAll(groups);
		q.off.addAll(off);
		q.dailies.clear();
		q.crops.putAll(crops);
		q.kingdom = false;
		q.approvalTarget = approvalTarget;
		q.cofferTarget = cofferTarget;
		q.topUpSlack = topUpSlack;
		q.compost = compost;
		q.protect = protect;
		q.keepSpiritTrees = keepSpiritTrees;
		q.includeUnseen = includeUnseen;
		q.lookaheadMinutes = lookaheadMinutes;
		q.contract = contract;
		return q;
	}

	public Settings group(Spot.Group g, boolean on)
	{
		if (on)
		{
			groups.add(g);
		}
		else
		{
			groups.remove(g);
		}
		return this;
	}

	public Settings spot(Spot s, boolean on)
	{
		if (on)
		{
			off.remove(s);
		}
		else
		{
			off.add(s);
		}
		return this;
	}

	public Settings daily(Daily d, boolean on)
	{
		if (on)
		{
			dailies.add(d);
		}
		else
		{
			dailies.remove(d);
		}
		return this;
	}

	/** Plant this in every patch of the kind, or null for the best the account can plant. */
	public Settings crop(PatchKind kind, Produce produce)
	{
		if (produce == null)
		{
			crops.remove(kind);
		}
		else
		{
			crops.put(kind, produce);
		}
		return this;
	}

	/** The running farming contract's crop when it grows in a guild patch Rounds tends, or null. */
	public Settings contract(Produce produce)
	{
		this.contract = produce;
		return this;
	}

	public Produce getContract()
	{
		return contract;
	}

	public Produce getCrop(PatchKind kind)
	{
		return crops.get(kind);
	}

	public boolean isKingdom()
	{
		return kingdom;
	}

	public Settings kingdom(boolean on)
	{
		this.kingdom = on;
		return this;
	}

	public int getApprovalTarget()
	{
		return approvalTarget;
	}

	public int getCofferTarget()
	{
		return cofferTarget;
	}

	public int getTopUpSlack()
	{
		return topUpSlack;
	}

	public Settings kingdomTargets(int approvalPercent, int coffer, int slack)
	{
		this.approvalTarget = Math.max(0, Math.min(100, approvalPercent));
		this.cofferTarget = Math.max(0, Math.min(Kingdom.MAX_COFFER, coffer));
		this.topUpSlack = Math.max(0, slack);
		return this;
	}

	public Compost getCompost()
	{
		return compost;
	}

	public Settings compost(Compost c)
	{
		this.compost = c;
		return this;
	}

	public boolean isProtect()
	{
		return protect;
	}

	public Settings protect(boolean p)
	{
		this.protect = p;
		return this;
	}

	public boolean isKeepSpiritTrees()
	{
		return keepSpiritTrees;
	}

	public Settings keepSpiritTrees(boolean k)
	{
		this.keepSpiritTrees = k;
		return this;
	}

	public boolean isIncludeUnseen()
	{
		return includeUnseen;
	}

	public Settings includeUnseen(boolean u)
	{
		this.includeUnseen = u;
		return this;
	}

	public int getLookaheadMinutes()
	{
		return lookaheadMinutes;
	}

	public Settings lookahead(int minutes)
	{
		this.lookaheadMinutes = Math.max(0, minutes);
		return this;
	}
}

