package com.codex.rounds.core;

/**
 * Picks how to reach a place and what it costs in seconds. Running covers about two tiles a
 * game tick, so walking is priced a little above 0.3 seconds a tile to allow for turns and doors.
 */
public final class Travel
{
	static final double SECONDS_PER_TILE = 0.36;
	/** Beyond this, walking from the last stop loses to any teleport. */
	static final int WALK_LIMIT = 140;

	private Travel()
	{
	}

	/** A way to a place: walking from where you are, a leg, or a leg to another place then a short step. */
	public static final class Way
	{
		private final Place place;
		private final Leg leg;
		private final boolean walk;
		private final int seconds;

		Way(Place place, Leg leg, boolean walk, int seconds)
		{
			this.place = place;
			this.leg = leg;
			this.walk = walk;
			this.seconds = seconds;
		}

		/** The place the leg lands at: the place itself, or the one it is reached through. */
		public Place getPlace()
		{
			return place;
		}

		/** The teleport or route to take, or null when walking from the last stop. */
		public Leg getLeg()
		{
			return leg;
		}

		public boolean isWalk()
		{
			return walk;
		}

		public int getSeconds()
		{
			return seconds;
		}

		public String describe()
		{
			if (walk)
			{
				return "Walk to " + place.getLabel();
			}
			return leg.getLabel();
		}
	}

	static int walkSeconds(Point a, Point b)
	{
		return (int) Math.round(a.distance(b) * SECONDS_PER_TILE) + 2;
	}

	/** The quickest way to a place from a spot, using only what the account can use. */
	public static Way best(Point from, Place place, Ability ability)
	{
		if (place.getVia() != null)
		{
			Way first = best(from, place.getVia(), ability);
			int local = walkSeconds(place.getVia().getAnchor(), place.getLocalPoint()) + 12;
			int measured = first.leg == null ? 0 : ability.pace(TravelTimer.key(place, first.leg));
			return new Way(first.place, first.leg, first.walk, measured > 0 ? measured : first.seconds + local);
		}
		Way best = null;
		if (from != null && from.sameMap(place.getAnchor()) && from.distance(place.getAnchor()) <= WALK_LIMIT)
		{
			best = new Way(place, null, true, walkSeconds(from, place.getAnchor()));
		}
		for (Leg leg : place.getLegs())
		{
			if (!ability.canUse(leg))
			{
				continue;
			}
			int measured = ability.pace(TravelTimer.key(place, leg));
			int s = measured > 0 ? measured : leg.overheadSeconds() + walkSeconds(leg.getLanding(), place.getAnchor());
			if (best == null || s < best.seconds)
			{
				best = new Way(place, leg, false, s);
			}
		}
		if (best == null)
		{
			// Every place lists plain directions last, so this only happens for a place with no legs.
			best = new Way(place, null, true, from == null ? 300 : walkSeconds(from, place.getAnchor()));
		}
		return best;
	}
}

package com.codex.rounds.core;

/**
 * Times each teleport leg of a round, from the moment the guide says to travel to the moment the player stands
 * in the stop, so later routes are planned with how long that leg really takes this player.
 */
public final class TravelTimer
{
	/** A finished leg: its key and the seconds it took. */
	public static final class Lap
	{
		private final String key;
		private final int seconds;

		Lap(String key, int seconds)
		{
			this.key = key;
			this.seconds = seconds;
		}

		public String getKey()
		{
			return key;
		}

		public int getSeconds()
		{
			return seconds;
		}
	}

	private Place target;
	private String key;
	private int estimate;
	private long startMs;

	public static String key(Place place, Leg leg)
	{
		return place.name() + "|" + leg.getLabel();
	}

	/** Called on every refresh while a round runs; returns a lap when the player arrives. */
	public Lap update(Step step, Route route, Point player, Ability ability, long nowMs)
	{
		if (target != null && target.contains(player))
		{
			Lap lap = null;
			int seconds = (int) Math.round((nowMs - startMs) / 1000.0);
			// A detour (banking, a chat, a break) is not the leg's time.
			if (key != null && seconds >= 2 && seconds <= estimate * 3 + 30)
			{
				lap = new Lap(key, seconds);
			}
			reset();
			return lap;
		}
		if (step.getKind() != Step.Kind.TRAVEL || step.getStopIndex() < 0 || step.getStopIndex() >= route.getStops().size())
		{
			reset();
			return null;
		}
		Place place = route.getStops().get(step.getStopIndex()).getPlace();
		if (place != target)
		{
			Travel.Way way = Travel.best(player, place, ability);
			target = place;
			key = way.getLeg() == null ? null : key(place, way.getLeg());
			estimate = way.getSeconds();
			startMs = nowMs;
		}
		return null;
	}

	public void reset()
	{
		target = null;
		key = null;
	}
}

