	SPIRIT_TREE("Spirit tree", PatchKind.SPIRIT_TREE, ItemID.PLANTPOT_SPIRIT_TREE_SAPLING, 320, 13, 0, 1, ItemID.PLANTPOT_SPIRIT_TREE_SAPLING, 83,
		ItemID.MM_MONKEY_NUTS, 5, ItemID.MM_MONKEY_BAR, 1, ItemID.LUNAR_GROUNDTOOTH, 1),
	CELASTRUS("Celastrus", PatchKind.CELASTRUS, ItemID.BATTLESTAFF, 160, 6, 0, 4, ItemID.PLANTPOT_CELASTRUS_TREE_SAPLING, 85, ItemID.CACTUS_POTATO, 8),
	REDWOOD("Redwood", PatchKind.REDWOOD, ItemID.REDWOOD_LOGS, 640, 11, 0, 1, ItemID.PLANTPOT_REDWOOD_TREE_SAPLING, 90, ItemID.DRAGONFRUIT, 6),
	HESPORI("Hespori", PatchKind.HESPORI, ItemID.HESPORI_SEED, 640, 4, 0, 2, ItemID.HESPORI_SEED, 65),
	CRYSTAL_TREE("Crystal tree", PatchKind.CRYSTAL_TREE, ItemID.PLANTPOT_CRYSTAL_TREE_SAPLING, 80, 7, 0, 1, ItemID.PLANTPOT_CRYSTAL_TREE_SAPLING, 74);

	private final String name;
	private final PatchKind kind;
	private final int itemId;
	private final int tickrate;
	private final int stages;
	private final int regrowTickrate;
	private final int harvestStages;
	private final int seedId;
	private final int level;
	/** Item, amount pairs the gardener takes to protect the crop, empty when it cannot be protected. */
	private final int[] payment;

	Produce(String name, PatchKind kind, int itemId, int tickrate, int stages, int regrowTickrate, int harvestStages,
		int seedId, int level, int... payment)
	{
		this.name = name;
		this.kind = kind;
		this.itemId = itemId;
		this.tickrate = tickrate;
		this.stages = stages;
		this.regrowTickrate = regrowTickrate;
		this.harvestStages = harvestStages;
		this.seedId = seedId;
		this.level = level;
		this.payment = payment;
	}

	public String getName()
	{
		return name;
	}

	public PatchKind getKind()
	{
		return kind;
	}

	/** The item the crop is shown with. */
	public int getItemId()
	{
		return itemId;
	}

	/** Minutes per growth tick. */
	public int getTickrate()
	{
		return tickrate;
	}

	/** States while growing, typically growth ticks plus one. */
	public int getStages()
	{
		return stages;
	}

	/** Minutes for the produce to regrow once picked, or zero when it does not. */
	public int getRegrowTickrate()
	{
		return regrowTickrate;
	}

	/** States while harvestable: the lives of the patch. */
	public int getHarvestStages()
	{
		return harvestStages;
	}

	/** What is planted: a seed, spore or sapling. */
	public int getSeedId()
	{
		return seedId;
	}

	/** Farming level needed to plant it. */
	public int getLevel()
	{
		return level;
	}

	public int[] getPayment()
	{
		return payment.clone();
	}

	public boolean isProtectable()
	{
		return payment.length > 0;
	}

	/** Minutes from planting to fully grown. */
	public int growMinutes()
	{
		return tickrate * Math.max(0, stages - 1);
	}

	/** Every crop that grows in a kind of patch, lowest level first. */
	public static java.util.List<Produce> forKind(PatchKind kind)
	{
		java.util.List<Produce> list = new java.util.ArrayList<>();
		for (Produce p : values())
		{
			if (p.kind == kind)
			{
				list.add(p);
			}
		}
		list.sort(java.util.Comparator.comparingInt(Produce::getLevel));
		return list;
	}
}

package com.codex.rounds.overlay;

import com.codex.rounds.CodexRoundsConfig;
import com.codex.rounds.ui.Theme;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;

/** Lights up the items the current step uses, in the pack, worn gear and the bank. */
public class ItemHighlight extends WidgetItemOverlay
{
	private final ItemManager itemManager;
	private final CodexRoundsConfig config;
	private volatile Set<Integer> items = Collections.emptySet();

	@Inject
	ItemHighlight(ItemManager itemManager, CodexRoundsConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
		showOnInventory();
		showOnEquipment();
		showOnBank();
	}

	public void setItems(Set<Integer> ids)
	{
		items = ids;
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightItems() || !items.contains(itemManager.canonicalize(itemId)) && !items.contains(itemId))
		{
			return;
		}
		Color color = config.highlightColor();
		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), color);
		g.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
		BufferedImage image = itemManager.getImage(itemId, widgetItem.getQuantity(), false);
		if (image != null)
		{
			g.drawImage(ImageUtil.fillImage(image, Theme.alpha(color, 60)), (int) bounds.getX(), (int) bounds.getY(), null);
		}
	}
}

package com.codex.rounds.overlay;

import com.codex.rounds.ui.Sigil;
import com.codex.rounds.ui.Theme;
import com.codex.rounds.ui.Ui;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The step plaque in the game view: where the round is, the one thing to do next in gilt
 * letters, a line of detail, and a thin bar for how much of the round is done.
 */
public class StepPlaque extends Overlay
{
	private static final int PAD = 8;
	private static final int MIN_WIDTH = 190;
	private static final int MAX_WIDTH = 290;

	private volatile Shown shown;

	/** What the plaque shows; null hides it. */
	public static final class Shown
	{
		final String over;
		final String title;
		final String detail;
		final String clock;
		final int done;
		final int total;

		public Shown(String over, String title, String detail, String clock, int done, int total)
		{
			this.over = over;
			this.title = title;
			this.detail = detail;
			this.clock = clock;
			this.done = done;
			this.total = total;
		}
	}

	public StepPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
	}

	public void show(Shown s)
	{
		shown = s;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Shown s = shown;
		if (s == null)
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();

		int icon = 18;
		int textX = PAD + icon + 8;
		int want = textX + Math.max(bold.stringWidth(s.title), Math.max(small.stringWidth(s.detail), small.stringWidth(s.over) + 40)) + PAD;
		int width = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, want));
		int room = width - textX - PAD;
		String[] lines = wrap(s.detail, small, room, 2);
		int height = PAD + small.getHeight() + bold.getHeight() + lines.length * small.getHeight() + 10;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 236), 0, height, Theme.alpha(Theme.INK_DEEP, 236)));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.GOLD, 150));
		g.draw(shape);
		g.setColor(Theme.alpha(java.awt.Color.WHITE, 14));
		g.drawLine(6, 1, width - 6, 1);

		Sigil.paint(g, PAD, PAD + 2, icon);

		int y = PAD + small.getAscent();
		g.setFont(Theme.small());
		Ui.shadowed(g, Ui.clip(s.over, small, room - small.stringWidth(s.clock) - 6), textX, y, Theme.TEXT_MUTED);
		if (!s.clock.isEmpty())
		{
			Ui.shadowed(g, s.clock, width - PAD - small.stringWidth(s.clock), y, Theme.GOLD_DIM);
		}
		y += bold.getHeight();
		g.setFont(Theme.title());
		Ui.shadowed(g, Ui.clip(s.title, bold, room), textX, y, Theme.GOLD_BRIGHT);
		g.setFont(Theme.small());
		for (String line : lines)
		{
			y += small.getHeight();
			Ui.shadowed(g, line, textX, y, Theme.TEXT);
		}

		if (s.total > 0)
		{
			int barY = height - 5;
			int barW = width - 2 * PAD;
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.fillRoundRect(PAD, barY, barW, 3, 3, 3);
			double t = Math.min(1, s.done / (double) s.total);
			int fill = (int) Math.round(barW * t);
			if (fill > 0)
			{
				g.setPaint(new GradientPaint(PAD, 0, Theme.GOLD_DIM, PAD + barW, 0, Theme.progressColor(t)));
				g.fillRoundRect(PAD, barY, fill, 3, 3, 3);
			}
		}
		return new Dimension(width, height);
	}

	static String[] wrap(String text, FontMetrics fm, int width, int maxLines)
	{
		if (text == null || text.isEmpty())
		{
			return new String[0];
		}
		java.util.List<String> out = new java.util.ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String trial = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(trial) > width && line.length() > 0)
			{
				out.add(line.toString());
				line = new StringBuilder(word);
				if (out.size() == maxLines)
				{
					break;
				}
			}
			else
			{
				line = new StringBuilder(trial);
			}
		}
		if (out.size() < maxLines && line.length() > 0)
		{
			out.add(line.toString());
		}
		else if (out.size() == maxLines)
		{
			String last = out.get(maxLines - 1);
			out.set(maxLines - 1, Ui.clip(last + " ...", fm, width));
		}
		return out.toArray(new String[0]);
	}
}

