import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Predicate;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Rounds side panel: the crest with how many chores are ready, then two pages. Round is
 * the next step, the stops in order and the pull list; Board is every patch, bird house,
 * daily and the kingdom with where each one stands.
 */
public class RoundsPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"round", "board"};

	private final ItemIcons icons;
	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Round", "Board");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane round = scroller();
	private final JScrollPane board = scroller();
	private Predicate<Task> done = t -> false;

	private View view = View.empty();

	public RoundsPanel(ItemIcons icons, Actions actions)
	{
		super(false);
		this.icons = icons;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(round, TABS[0]);
		content.add(board, TABS[1]);
		add(content, BorderLayout.CENTER);
		tabs.onChange(this::showTab);
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/**
	 * Called on the Swing thread whenever anything shown changes.
	 *
	 * @param done tells which chores of the round are finished
	 */
	public void update(View view, Predicate<Task> done)
	{
		this.view = view;
		this.done = done;
		updateCrest();
		rebuild();
	}

	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
	}

	private void updateCrest()
	{
		if (!view.known)
		{
			crest.update("READY NOW", null, false, view.loggedIn ? "Reading your account" : "Log in to read your patches", null, Theme.TEXT_MUTED, Theme.GOLD);
			return;
		}
		Board b = view.board;
		int ready = (int) b.count(Status.READY);
		String status;
		String brief = null;
		Color color = Theme.TEXT_MUTED;
		if (view.running && view.step != null && view.step.getTotal() > 0)
		{
			status = view.step.getDone() + " of " + view.step.getTotal() + " done, " + Format.clock(view.now - view.startedAt);
			color = Theme.GOLD;
		}
		else
		{
			Board.Entry next = b.nextUp();
			if (next != null)
			{
				status = "Next: " + next.getTitle() + " in " + Format.shortDuration(next.getReadyAt() - view.now);
				brief = "Next in " + Format.shortDuration(next.getReadyAt() - view.now);
			}
			else
			{
				status = ready > 0 ? "Ready for a round" : "Nothing growing";
			}
		}
		crest.update(view.running ? "ROUND UNDER WAY" : "READY NOW", ready, false, status, brief, color, ready > 0 ? Theme.GREEN : Theme.GOLD);
	}

	private void rebuild()
	{
		round.setViewportView(buildRound());
		board.setViewportView(buildBoard());
		revalidate();
		repaint();
	}

	private StackPanel buildRound()
	{
		StackPanel list = new StackPanel(6, 8);
		if (!view.known)
		{
			list.add(note(view.loggedIn ? "Reading your patches, dailies and kingdom."
				: "Log in and Rounds reads your patches, bird houses, dailies and kingdom. RuneLite's Time Tracking history is picked up too."));
			return list;
		}
		Route route = view.route;
		Step step = view.step;

		list.add(new SectionHeader(view.running ? "Next step" : "Your round", view.running && step.getTotal() > 0 ? step.getDone() + "/" + step.getTotal() : null));
		list.add(stepCard(route, step));

		if (!route.isEmpty())
		{
			list.space(2);
			list.add(new SectionHeader("The round", route.getStops().size() + (route.getStops().size() == 1 ? " stop" : " stops")));
			int i = 0;
			for (Stop s : route.getStops())
			{
				list.add(new StopRow(i + 1, s, view.running && step.getStopIndex() == i, done));
				i++;
			}

			list.space(2);
			list.add(new SectionHeader("Bring", "pull list"));
			if (!view.bankKnown)
			{
				list.add(note("Open your bank once so Rounds can plan with the teleports and supplies you own."));
			}
			Need.Kind kind = null;
			for (Need n : route.getPulls())
			{
				if (n.getKind() != kind)
				{
					kind = n.getKind();
					list.add(sub(kind.getLabel()));
				}
				list.add(pullRow(n));
			}
			if (!route.getPulls().isEmpty())
			{
				list.space(1);
				JPanel bar = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
				bar.setOpaque(false);
				bar.add(new CodexButton("Lay it out in my bank", false, actions::bankTab));
				list.add(bar);
			}
		}
		if (view.lastRound != null)
		{
			list.space(2);
			list.add(note(view.lastRound));
		}
		return list;
	}

	private JComponent stepCard(Route route, Step step)
	{
		Card card = new Card(new BorderLayout(0, 6)).accent(view.running ? Theme.GOLD : Theme.TEAL).highlighted(view.running);
		StackPanel body = new StackPanel(3, 0);
		int width = WIDTH - 40;
		String title;
		String detail;
		if (route.isEmpty())
		{
			title = "Nothing due";
			Board.Entry next = view.board.nextUp();
			detail = next == null ? "Every chore is growing or done." : next.getTitle() + " is ready in " + Format.duration(next.getReadyAt() - view.now) + ".";
		}
		else if (!view.running)
		{
			title = route.taskCount() + (route.taskCount() == 1 ? " chore, " : " chores, ") + route.getStops().size()
				+ (route.getStops().size() == 1 ? " stop" : " stops");
			detail = "About " + Format.duration(route.getSeconds()) + " with what you own. Start the round and Rounds lights the way.";
		}
		else
		{
			title = step.getTitle();
			detail = step.getDetail();
		}
		body.add(Ui.wrapped(title, Theme.title(), Theme.GOLD_BRIGHT, width));
		body.add(Ui.wrapped(detail, Theme.small(), Theme.TEXT, width));
		if (!view.running && view.forecast != null)
		{
			body.add(Ui.wrapped(view.forecast, Theme.small(), Theme.GREEN, width));
		}
		if (view.running && !step.getItems().isEmpty())
		{
			body.add(iconStrip(step.getItems()));
		}
		card.add(body, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		if (view.running)
		{
			buttons.add(new CodexButton("Skip", false, actions::skip));
			buttons.add(spacer());
			buttons.add(new CodexButton("Replan", false, actions::replan));
			buttons.add(spacer());
			buttons.add(new CodexButton("End", false, actions::stop));
		}
		else
		{
			// Two buttons fit the card: the quick Fossil Island loop takes Replan's place when it is on offer.
			if (!route.isEmpty())
			{
				buttons.add(new CodexButton("Start round", true, actions::start));
			}
			if (quickReady())
			{
				if (buttons.getComponentCount() > 0)
				{
					buttons.add(spacer());
				}
				buttons.add(new CodexButton("Quick loop", false, actions::startQuick));
			}
			else if (!route.isEmpty())
			{
				buttons.add(spacer());
				buttons.add(new CodexButton("Replan", false, actions::replan));
			}
		}
		if (buttons.getComponentCount() > 0)
		{
			card.add(buttons, BorderLayout.SOUTH);
		}
		return card;
	}

	private static JComponent spacer()
	{
		JPanel s = new JPanel();
		s.setOpaque(false);
		s.setPreferredSize(new Dimension(5, 1));
		return s;
	}

	private JComponent iconStrip(List<Integer> items)
	{
		JPanel strip = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
		strip.setOpaque(false);
		int shown = 0;
		for (int id : items)
		{
			if (shown++ >= 4)
			{
				break;
			}
			BufferedImage[] holder = new BufferedImage[1];
			JComponent well = new JComponent()
			{
				@Override
				protected void paintComponent(java.awt.Graphics graphics)
				{
					java.awt.Graphics2D g = (java.awt.Graphics2D) graphics.create();
					Theme.smooth(g);
					Well.paint(g, 0, 0, holder[0], Theme.alpha(Theme.GOLD, 120));
					g.dispose();
				}
			};
			holder[0] = icons.icon(id, well::repaint);
			well.setPreferredSize(new Dimension(Well.SIZE + 5, Well.SIZE + 1));
			strip.add(well);
		}
		return strip;
	}

	/** Whether a bird house or seaweed patch is ready, so a quick Fossil Island loop is worth offering. */
	private boolean quickReady()
	{
		if (view.board == null)
		{
			return false;
		}
		for (Board.Entry e : view.board.getEntries())
		{
			if (e.getStatus() == Status.READY && e.getSpot() != null && Settings.QUICK.contains(e.getSpot().getGroup()))
			{
				return true;
			}
		}
		return false;
	}

	private Row pullRow(Need n)
	{
		int carried = view.carrying(n.getItems());
		int banked = view.banked(n.getItems());
		String badge;
		Color color;
		if (carried >= n.getQuantity())
		{
			badge = "Packed";
			color = Theme.GREEN;
		}
		else if (Leprechaun.holds(n) && view.leprechaunFirst && carried + view.stored(n.getItems()) >= n.getQuantity())
		{
			badge = "Leprechaun";
			color = Theme.GREEN;
		}
		else if (carried + banked >= n.getQuantity())
		{
			badge = "In bank";
			color = Theme.GOLD;
		}
		else if (n.isOptional())
		{
			badge = "Optional";
			color = Theme.TEXT_FAINT;
		}
		else if (!view.bankKnown)
		{
			badge = "Check";
			color = Theme.TEXT_MUTED;
		}
		else
		{
			badge = "Short";
			color = Theme.BLOOD;
		}
		String title = (n.getQuantity() > 1 ? Format.stack(n.getQuantity()) + " x " : "") + n.getLabel();
		return new Row(icons, n.getItemId(), title, n.getWhy(), badge, color, false);
	}

	private StackPanel buildBoard()
	{
		StackPanel list = new StackPanel(5, 8);
		if (!view.known)
		{
			list.add(note("Log in to see every patch, bird house and daily."));
			return list;
		}
		Board b = view.board;
		for (Spot.Group group : Spot.Group.values())
		{
			List<Board.Entry> rows = new ArrayList<>();
			for (Board.Entry e : b.getEntries())
			{
				if (e.getType() == Board.Type.SPOT && e.getSpot().getGroup() == group)
				{
					rows.add(e);
				}
			}
			addGroup(list, group.getLabel(), rows);
		}
		List<Board.Entry> dailies = new ArrayList<>();
		Board.Entry kingdom = null;
		for (Board.Entry e : b.getEntries())
		{
			if (e.getType() == Board.Type.DAILY)
			{
				dailies.add(e);
			}
			else if (e.getType() == Board.Type.KINGDOM)
			{
				kingdom = e;
			}
		}
		if (dailies.isEmpty())
		{
			list.add(new SectionHeader("Dailies"));
			list.add(note("Dailies show once you log in."));
		}
		else
		{
			addGroup(list, "Dailies", dailies);
		}
		list.add(new SectionHeader("Kingdom of Miscellania"));
		list.add(kingdomCard(b.getKingdom(), kingdom));
		return list;
	}

	private void addGroup(StackPanel list, String label, List<Board.Entry> rows)
	{
		if (rows.isEmpty())
		{
			return;
		}
		long ready = rows.stream().filter(e -> e.getStatus() == Status.READY).count();
		list.add(new SectionHeader(label, ready > 0 ? ready + " ready" : null));
		rows.sort(Comparator.comparingInt((Board.Entry e) -> order(e.getStatus())).thenComparingLong(Board.Entry::getReadyAt));
		for (Board.Entry e : rows)
		{
			list.add(boardRow(e));
		}
	}

	private static int order(Status s)
	{
		switch (s)
		{
			case READY:
				return 0;
			case GROWING:
				return 1;
			case UNSEEN:
				return 2;
			case DONE:
				return 3;
			case LOCKED:
				return 4;
			default:
				return 5;
		}
	}

	private Row boardRow(Board.Entry e)
	{
		String badge;
		switch (e.getStatus())
		{
			case READY:
				badge = "Ready";
				break;
			case GROWING:
				badge = e.getReadyAt() > view.now ? Format.shortDuration(e.getReadyAt() - view.now) : "Soon";
				break;
			case UNSEEN:
				badge = "Unseen";
				break;
			case DONE:
				badge = e.getType() == Board.Type.DAILY ? "Claimed" : "Done";
				break;
			case LOCKED:
				badge = "Locked";
				break;
			default:
				badge = "Off";
				break;
		}
		String title = e.getType() == Board.Type.SPOT ? e.getSpot().getLabel() : e.getTitle();
		String sub = e.getDetail();
		if (e.getType() == Board.Type.SPOT && e.getReading() != null && e.getReading().getProduce() != null)
		{
			sub = e.getReading().getProduce().getName() + ": " + sub.substring(0, 1).toLowerCase() + sub.substring(1);
		}
		boolean dim = e.getStatus() == Status.OFF || e.getStatus() == Status.LOCKED || e.getStatus() == Status.DONE;
		return new Row(icons, e.getItemId(), title, sub, badge, Theme.status(e.getStatus()), dim);
	}

	private JComponent kingdomCard(Kingdom k, Board.Entry entry)
	{
		Card card = new Card(new BorderLayout());
		StackPanel body = new StackPanel(4, 0);
		if (k == null)
		{
			body.add(Ui.wrapped("Visit Miscellania once after Throne of Miscellania and Rounds keeps watch on approval and the coffer.",
				Theme.small(), Theme.TEXT_MUTED, WIDTH - 40));
		}
		else
		{
			int pct = k.approvalPercent();
			body.add(new Meter("Approval", pct + "%", pct / 100.0, pct >= 90 ? Theme.GREEN : pct >= 60 ? Theme.GOLD : Theme.EMBER, null));
			double full = Kingdom.fullPayoutCoffer(k.isRoyalTrouble());
			body.add(new Meter("Coffer", Format.stack(k.getCoffer()), k.getCoffer() / full,
				k.getCoffer() >= full ? Theme.GREEN : Theme.GOLD, null));
			String state = entry == null ? "" : entry.getStatus() == Status.READY ? "Due a visit" : entry.getStatus() == Status.OFF ? "Left out of rounds" : "Looked after";
			int days = k.daysUntilApprovalBelow(60);
			String foot = state + (k.isEstimated() ? ", estimated" : "") + (days > 0 ? ". Approval stays above 60% for " + days + (days == 1 ? " day" : " days") : "");
			body.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 40));
		}
		card.add(body, BorderLayout.CENTER);
		return card;
	}

	private static JComponent note(String text)
	{
		Card card = new Card(new BorderLayout());
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 40), BorderLayout.CENTER);
		return card;
	}

	private static JComponent sub(String text)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.setBorder(new EmptyBorder(2, 2, 0, 0));
		p.add(Ui.label(text, Theme.small(), Theme.TEXT_FAINT), BorderLayout.CENTER);
		return p;
	}
}

package com.codex.rounds.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * One line of the board or the pull list: an item in its well, a title, a quiet second line
 * and a coloured badge on the right that says where it stands.
 */
public class Row extends JComponent
{
	static final int HEIGHT = 40;

	private final ItemIcons icons;
	private final int itemId;
	private final String title;
	private final String sub;
	private final String badge;
	private final Color badgeColor;
	private final boolean dim;
	private BufferedImage icon;

	public Row(ItemIcons icons, int itemId, String title, String sub, String badge, Color badgeColor, boolean dim)
	{
		this.icons = icons;
		this.itemId = itemId;
		this.title = title;
		this.sub = sub;
		this.badge = badge;
		this.badgeColor = badgeColor;
		this.dim = dim;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setToolTipText(sub == null || sub.isEmpty() ? title : title + ": " + sub);
		if (icons != null && itemId >= 0)
		{
			icon = icons.icon(itemId, this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 2, 8, 8);
		g.setPaint(new GradientPaint(0, 0, dim ? Theme.mix(Theme.CARD, Theme.INK, 0.5) : Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);

		if (icons != null && itemId >= 0)
		{
			Well.paint(g, 3, 3, icon, null);
		}
		else
		{
			// No item: a status dot sits where the well would be.
			g.setColor(badgeColor);
			g.fill(new Ellipse2D.Float(14, h / 2f - 4, 8, 8));
		}

		int x = 44;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int badgeW = badge == null || badge.isEmpty() ? 0 : small.stringWidth(badge) + 12;
		int room = w - x - badgeW - 8;

		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(title, body, room), x, 17, dim ? Theme.TEXT_MUTED : Theme.TEXT);
		if (sub != null && !sub.isEmpty())
		{
			g.setFont(Theme.small());
			Ui.shadowed(g, Ui.clip(sub, small, room), x, 31, Theme.TEXT_FAINT);
		}

		if (badgeW > 0)
		{
			g.setFont(Theme.small());
			int bx = w - badgeW - 6;
			int by = h / 2 - 8;
			RoundRectangle2D pill = new RoundRectangle2D.Float(bx, by, badgeW, 15, 8, 8);
			g.setColor(Theme.alpha(badgeColor, 34));
			g.fill(pill);
			g.setColor(Theme.alpha(badgeColor, 150));
			g.draw(pill);
			Ui.shadowed(g, badge, bx + 6, by + 11, badgeColor);
		}
		g.dispose();
	}
}

package com.codex.rounds.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.rounds.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.rounds.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** The Rounds mark: a green sprout inside a gilt arrow that runs nearly all the way round. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float cx = x + 8 * s;
		float cy = y + 8 * s;
		float r = 6.2f * s;

		// The round: a gilt arc from the top, clockwise, stopping short so the arrowhead shows.
		Arc2D arc = new Arc2D.Float(cx - r, cy - r, r * 2, r * 2, 70, -300, Arc2D.OPEN);
		g.setStroke(new BasicStroke(Math.max(2.4f, 2.6f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(arc);
		g.setStroke(new BasicStroke(Math.max(1.2f, 1.5f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setPaint(new GradientPaint(x, y, Theme.GOLD_BRIGHT, x, y + size, Theme.GOLD_DIM));
		g.draw(arc);

		// The arrowhead at the arc's end, pointing on round the circle towards the gap at the top.
		double end = Math.toRadians(70 - 300);
		float ex = (float) (cx + r * Math.cos(end));
		float ey = (float) (cy - r * Math.sin(end));
		float dx = (float) Math.sin(end);
		float dy = (float) Math.cos(end);
		float nx = (float) Math.cos(end);
		float ny = (float) -Math.sin(end);
		Path2D head = new Path2D.Float();
		head.moveTo(ex + dx * 2.8f * s, ey + dy * 2.8f * s);
		head.lineTo(ex + nx * 2.1f * s - dx * 0.4f * s, ey + ny * 2.1f * s - dy * 0.4f * s);
		head.lineTo(ex - nx * 2.1f * s - dx * 0.4f * s, ey - ny * 2.1f * s - dy * 0.4f * s);
		head.closePath();
		g.setStroke(new BasicStroke(Math.max(0.6f, 0.5f * s)));
		g.setColor(Theme.GOLD_BRIGHT);
		g.fill(head);
		g.setColor(Theme.INK_DEEP);
		g.draw(head);

		// The sprout: a stem and two leaves, lit from above.
		g.setStroke(new BasicStroke(Math.max(0.9f, 0.9f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.mix(Theme.GREEN, Theme.INK_DEEP, 0.25));
		g.drawLine(Math.round(cx), Math.round(cy + 3.2f * s), Math.round(cx), Math.round(cy - 0.6f * s));
		Path2D left = leaf(cx, cy - 0.2f * s, -1, s);
		Path2D right = leaf(cx, cy - 1.0f * s, 1, s);
		g.setPaint(new GradientPaint(cx, cy - 4 * s, Theme.mix(Theme.GREEN, Theme.TEXT, 0.35), cx, cy + 2 * s, Theme.mix(Theme.GREEN, Theme.INK_DEEP, 0.3)));
		g.fill(left);
		g.fill(right);
		g.setStroke(new BasicStroke(Math.max(0.5f, 0.45f * s)));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.draw(left);
		g.draw(right);

		// A small mound of earth at the sprout's foot.
		g.setColor(Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.4));
		g.fill(new Ellipse2D.Float(cx - 2.4f * s, cy + 2.6f * s, 4.8f * s, 1.8f * s));
	}

	private static Path2D leaf(float bx, float by, int side, float s)
	{
		float tipX = bx + side * 3.6f * s;
		float tipY = by - 2.6f * s;
		Path2D p = new Path2D.Float();
		p.moveTo(bx, by);
		p.quadTo(bx + side * 0.6f * s, tipY - 0.6f * s, tipX, tipY);
		p.quadTo(bx + side * 3.2f * s, by + 0.4f * s, bx, by);
		p.closePath();
		return p;
	}
}

package com.codex.rounds.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.rounds.ui;

import com.codex.rounds.core.Stop;
import com.codex.rounds.core.Task;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import java.util.function.Predicate;
import javax.swing.JComponent;

/**
 * One stop of the round: a numbered seal, the place, how to get there, and its chores with a
 * tick against each one done. The current stop is lit in gold; finished stops fade back.
 */
public class StopRow extends JComponent
{
	private static final int HEAD = 34;
	private static final int LINE = 14;

	private final int number;
	private final Stop stop;
	private final boolean current;
	private final Predicate<Task> done;

	public StopRow(int number, Stop stop, boolean current, Predicate<Task> done)
	{
		this.number = number;
		this.stop = stop;
		this.current = current;
		this.done = done;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEAD + stop.getTasks().size() * LINE + 6));
	}

	private boolean allDone()
	{
		for (Task t : stop.getTasks())
		{
			if (!done.test(t))
			{
				return false;
			}
		}
		return true;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		boolean finished = allDone();

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 2, 9, 9);
		Color top = current ? Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.18) : finished ? Theme.mix(Theme.CARD, Theme.INK, 0.5) : Theme.CARD_TOP;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(current ? Theme.alpha(Theme.GOLD, 160) : Theme.STROKE_SOFT);
		g.draw(shape);

		// The seal: a numbered disc, gold for the current stop, green with a tick when finished.
		float cx = 17;
		float cy = 17;
		float r = 10;
		Color seal = finished ? Theme.GREEN : current ? Theme.GOLD : Theme.GOLD_DIM;
		g.setPaint(new GradientPaint(0, cy - r, Theme.mix(seal, Color.WHITE, 0.2), 0, cy + r, Theme.mix(seal, Theme.INK_DEEP, 0.35)));
		g.fill(new Ellipse2D.Float(cx - r, cy - r, r * 2, r * 2));
		g.setColor(Theme.INK_DEEP);
		g.draw(new Ellipse2D.Float(cx - r, cy - r, r * 2, r * 2));
		if (finished)
		{
			tick(g, cx - 4.5f, cy - 0.5f, 1.1f, Theme.INK_DEEP);
		}
		else
		{
			g.setFont(Theme.title());
			FontMetrics fm = g.getFontMetrics();
			String n = String.valueOf(number);
			g.setColor(Theme.INK_DEEP);
			g.drawString(n, Math.round(cx - fm.stringWidth(n) / 2f), Math.round(cy + fm.getAscent() / 2f - 2));
		}

		int x = 34;
		int room = w - x - 8;
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(stop.getPlace().getLabel(), body, room), x, 15, finished ? Theme.TEXT_MUTED : current ? Theme.GOLD_BRIGHT : Theme.TEXT);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(stop.getWay().describe(), small, room), x, 28, Theme.TEXT_FAINT);

		List<Task> tasks = stop.getTasks();
		int y = HEAD + 8;
		for (Task t : tasks)
		{
			boolean d = done.test(t);
			if (d)
			{
				tick(g, x + 1, y - 4, 0.75f, Theme.GREEN);
			}
			else
			{
				g.setColor(current ? Theme.GOLD : Theme.GOLD_DIM);
				Path2D diamond = new Path2D.Float();
				diamond.moveTo(x + 3, y - 7);
				diamond.lineTo(x + 6, y - 4);
				diamond.lineTo(x + 3, y - 1);
				diamond.lineTo(x, y - 4);
				diamond.closePath();
				g.fill(diamond);
			}
			String line = t.getSpot() != null ? t.getSpot().kindName() + ", " + t.getSpot().getLabel() : t.getTitle();
			Ui.shadowed(g, Ui.clip(line, small, room - 12), x + 11, y, d ? Theme.TEXT_FAINT : Theme.TEXT_MUTED);
			y += LINE;
		}
		g.dispose();
	}

	static void tick(Graphics2D g, float x, float y, float scale, Color color)
	{
		Path2D p = new Path2D.Float();
		p.moveTo(x, y);
		p.lineTo(x + 3 * scale, y + 3 * scale);
		p.lineTo(x + 9 * scale, y - 4 * scale);
		g.setStroke(new BasicStroke(1.8f * scale, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(color);
		g.draw(p);
		g.setStroke(new BasicStroke(1));
	}
}

package com.codex.rounds.ui;

import com.codex.rounds.core.Status;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Rounds colours a chore by where it stands: green when it is ready to pick, gold while it
 * grows, violet when it has never been seen, and faint ink when it is done or set aside.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	/** The colour of a chore's standing. */
	public static Color status(Status status)
	{
		switch (status)
		{
			case READY:
				return GREEN;
			case GROWING:
				return GOLD;
			case UNSEEN:
				return VIOLET;
			case LOCKED:
				return BLOCKED;
			default:
				return TEXT_FAINT;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.rounds.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.rounds.ui;

import com.codex.rounds.core.Board;
import com.codex.rounds.core.Route;
import com.codex.rounds.core.Step;
import java.util.Collections;
import java.util.Map;

/** Everything the panel shows, taken in one go on the client thread. */
public final class View
{
	public final boolean loggedIn;
	public final boolean known;
	public final Board board;
	public final Route route;
	public final Step step;
	public final boolean running;
	public final long startedAt;
	public final long now;
	public final boolean bankKnown;
	/** Items in the pack and worn, then what the bank holds. */
	public final Map<Integer, Integer> carried;
	public final Map<Integer, Integer> bank;
	public final String lastRound;
	/** Tools and compost with the tool leprechaun. */
	public final Map<Integer, Integer> stored;
	/** Whether the round's first stop has a leprechaun to take them from. */
	public final boolean leprechaunFirst;
	/** A suggestion to wait for more chores, or null. */
	public final String forecast;

	public View(boolean loggedIn, boolean known, Board board, Route route, Step step, boolean running, long startedAt, long now,
		boolean bankKnown, Map<Integer, Integer> carried, Map<Integer, Integer> bank, String lastRound, Map<Integer, Integer> stored, boolean leprechaunFirst, String forecast)
	{
		this.forecast = forecast;
		this.stored = stored;
		this.leprechaunFirst = leprechaunFirst;
		this.loggedIn = loggedIn;
		this.known = known;
		this.board = board;
		this.route = route;
		this.step = step;
		this.running = running;
		this.startedAt = startedAt;
		this.now = now;
		this.bankKnown = bankKnown;
		this.carried = carried;
		this.bank = bank;
		this.lastRound = lastRound;
	}

	public static View empty()
	{
		return new View(false, false, null, Route.EMPTY, Step.IDLE, false, 0, 0, false, Collections.emptyMap(), Collections.emptyMap(), null, Collections.emptyMap(), false, null);
	}

	int stored(int... ids)
	{
		int n = 0;
		for (int id : ids)
		{
			n += stored.getOrDefault(id, 0);
		}
		return n;
	}

	int carrying(int... ids)
	{
		int n = 0;
		for (int id : ids)
		{
			n += carried.getOrDefault(id, 0);
		}
		return n;
	}

	int banked(int... ids)
	{
		int n = 0;
		for (int id : ids)
		{
			n += bank.getOrDefault(id, 0);
		}
		return n;
	}
}

package com.codex.rounds.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The dark slot an item sits in, like a bank slot, with the stack drawn in the game's colours. */
final class Well
{
	static final int SIZE = 32;

	private Well()
	{
	}

	static void paint(Graphics2D g, int x, int y, BufferedImage icon, Color rim)
	{
		RoundRectangle2D well = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, SIZE + 4, SIZE - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + SIZE, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		g.setColor(rim == null ? Theme.STROKE_SOFT : rim);
		g.draw(well);
		if (icon != null)
		{
			g.drawImage(icon, x + 2 + (SIZE - icon.getWidth()) / 2, y + (SIZE - icon.getHeight()) / 2 + 1, null);
		}
	}
}

