	static int val(PatchKind k, Produce p, Action a)
	{
		for (int v = 0; v < 256; v++)
		{
			com.codex.rounds.core.farming.PatchState st = k.forVarbitValue(v);
			if (st != null && st.getProduce() == p && st.getAction() == a)
			{
				return v;
			}
		}
		throw new IllegalStateException(k + " " + p + " " + a);
	}

